ST.xhtml:
// === 🔀 §1 ARBITRAGE DES MODES MACHINE & INTENTION OPÉRATEUR ===
{region "§1 Modes machine"}

instModes(
    Enable                  := TRUE,
    Reset                   := GVL_IHM.Modes.Cmd.BtnModeReset,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    SelMode                 := GVL_IHM.Modes.Cmd.SelMode,
    SelSyncEnable           := GVL_IHM.M1M2Sync.Cmd.SelSyncEnable,
    InhibitM1Request        := GVL_IHM.M1TreuilRetenue.Cmd.BtnInhibit,
    InhibitM2Request        := GVL_IHM.M2TreuilBenne.Cmd.BtnInhibit,
    SelHomingApproachEnable := GVL_IHM.Commun.Cfg.SelHomingApproachEnable,
    EncoderFaultPresent     := (PRG_02_Acquisition.HwIn.Winch.COD1_DeviceState <> DEVICE_STATE.RUNNING) OR (PRG_02_Acquisition.HwIn.Winch.COD2_DeviceState <> DEVICE_STATE.RUNNING),
    JoystickWinchSelectRequest := GVL_IHM.Modes.Cmd.SelJoystickWinch,
    SelMaintenanceZoneAccess := GVL_IHM.TranslationM3.Cmd.TglMaintenanceZoneAccess,
    // T248 — sequencement auto benne en couple (force temporairement le sel. a 2)
    CoupledBucketSeqEnable  := GVL_IHM.Commun.Cfg.TglEnableCoupledBucketSequencing,
    M3AtTremie              := PRG_05_Translation.Data.TranslationState.LimitSwitchTremie,
    AllowWinchMoveAtTremie  := GVL_IHM.TranslationM3.Cmd.TglAllowWinchMoveAtTremie,
    JoystickPull            := PRG_02_Acquisition.Data.Joystick.AxisY.DirectionPositive,
    JoystickPush            := PRG_02_Acquisition.Data.Joystick.AxisY.DirectionNegative,
    BucketIsOpen            := PRG_04_Treuils_Benne.Data.BucketState.MechState.IsOpen,
    BucketIsClosed          := PRG_04_Treuils_Benne.Data.BucketState.MechState.IsClosed,
    // Arrêt mécanique confirmé des treuils (condition de bascule N1/N2, AF-05 §4bis)
    M1ContactorsReleased      := PRG_02_Acquisition.HwIn.Winch.M1_ContactorsReleased_DI,
    M1BrakeIsOpen             := PRG_02_Acquisition.HwIn.Winch.M1_BrakeIsOpen_DI,
    M1SpeedAbsMps             := PRG_02_Acquisition.Data.EncoderM1.Measurement.Speed_Mps,
    M2ContactorsReleased      := PRG_02_Acquisition.HwIn.Winch.M2_ContactorsReleased_DI,
    M2BrakeIsOpen             := PRG_02_Acquisition.HwIn.Winch.M2_BrakeIsOpen_DI,
    M2SpeedAbsMps             := PRG_02_Acquisition.Data.EncoderM2.Measurement.Speed_Mps,
    // États homing (levée du re-homing obligatoire)
    M1HomingDone              := PRG_02_Acquisition.Data.EncoderM1.Measurement.HomingLifecycle.Done,
    M1Homed                   := PRG_02_Acquisition.Data.EncoderM1.Homed,
    M1HomingSuspect           := PRG_02_Acquisition.Data.EncoderM1.HomingSuspect,
    M2HomingDone              := PRG_02_Acquisition.Data.EncoderM2.Measurement.HomingLifecycle.Done,
    M2Homed                   := PRG_02_Acquisition.Data.EncoderM2.Homed,
    M2HomingSuspect           := PRG_02_Acquisition.Data.EncoderM2.HomingSuspect,
    // Usage effectif d'un override/bypass de position (producteur PRG_04, lag 1 scan
    // assumé : PRG_04 est de rang 04, ce programme de rang 03)
    M1PositionLimitOverridden := PRG_04_Treuils_Benne.Data.PositionLimitOverriddenM1,
    M2PositionLimitOverridden := PRG_04_Treuils_Benne.Data.PositionLimitOverriddenM2,
    MachineHomed     := PRG_02_Acquisition.Data.MachineHoming.Homed,
    // Restauration boot des drapeaux de re-homing (miroir PERSISTENT)
    BootHomingRequiredM1      := GVL_PERSISTENT._MaintM1HomingRequired,
    BootHomingRequiredM2      := GVL_PERSISTENT._MaintM2HomingRequired
);

// Miroir persistant du re-homing obligatoire (pattern FB_MirrorBypassRetain) :
// FB_Modes est le producteur unique de la décision ; GVL_PERSISTENT n'est que la mémoire.
GVL_PERSISTENT._MaintM1HomingRequired := instModes.Auth.HomingRequiredM1;
GVL_PERSISTENT._MaintM2HomingRequired := instModes.Auth.HomingRequiredM2;

// Qualification de l'intention opérateur both (M1+M2) dans le même scan.
// Homme-mort QUALIFIÉ (Data.Joystick.DeadmanArmed) — même source que l'arbitrage
// (Joystick.DeadmanArmed) : les assistants et la commande réelle partagent
// la même décision, plus de divergence raw/qualifié.
IF GVL_IHM.Modes.Cmd.TglJoystickMaster THEN
    WinchBothMotionDirection := PRG_02_Acquisition.Data.Joystick.AxisY.Direction;
    WinchBothMotionActive := PRG_02_Acquisition.Data.Joystick.DeadmanArmed
                                     AND (instModes.Auth.JoystickWinchSelectArbitrated = 0);
ELSE
    IF GVL_IHM.Commun.BtnWinchBothAscent THEN
        WinchBothMotionDirection := 1;
    ELSIF GVL_IHM.Commun.BtnWinchBothDescent THEN
        WinchBothMotionDirection := -1;
    ELSE
        WinchBothMotionDirection := 0;
    END_IF;
    WinchBothMotionActive := (WinchBothMotionDirection <> 0);
END_IF;

// Posture de départ du cycle SEMI_AUTO (condition AX1_INIT) : treuils M1/M2 dans la
// plage de position haute (± CST_CycleInitWindowM autour de la limite haute configurée)
// ET chariot M3 PAS à droite de P1 (côté maintenance interdit). Le positionnement fin
// sur P1 est fait ensuite en AX2. Calculé ici — FB_CycleSemiAuto ne fait que consommer.
CycleWinchesAtTopOk :=
    (ABS(PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM - _CommunCfgPersist.CfgCableLimitAscent_M) <= CST_CycleInitWindowM)
    AND (ABS(PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM - _CommunCfgPersist.CfgCableLimitAscent_M) <= CST_CycleInitWindowM);

// Posture de départ complète (AX1_INIT) = treuils en haut ET chariot M3 PAS à droite de P1.
CycleInitPositionOk := NOT PRG_05_Translation.Data.M3_AtMaintenanceStable AND CycleWinchesAtTopOk;

{endregion}


// === 🤿 §2 ASSISTANTS DE DRAGAGE (PLONGÉE & EXTRACTION) ===
{region "§2 Assistants de dragage"}

// 1. Garde-clear de la confirmation manuelle et bypass fond touché
IF NOT (instModes.Auth.Mode = E_Mode.MAINT_N1 OR instModes.Auth.Mode = E_Mode.MAINT_N2)
   OR NOT PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI
   OR PRG_07_Supervision.FaultMachineReset_IHM
   OR (WinchBothMotionActive AND (WinchBothMotionDirection = -1)) THEN
    GVL_IHM.CycleDiveSearch.Cmd.TglBucketAtBottomConfirmed := FALSE;
    BypassKoboldBottomTouched := FALSE;
END_IF;
ManualBottomPositionConfirmed := GVL_IHM.CycleDiveSearch.Cmd.TglBucketAtBottomConfirmed;

// 2. Détection front descendant Kobold sous bypass
BypassKoboldFallEdge(CLK := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI);
IF GVL_IHM.CycleDiveSearch.Cmd.TglBypassDiveSearchSequence
   AND WinchBothMotionActive AND (WinchBothMotionDirection = -1)
   AND BypassKoboldFallEdge.Q THEN
    BypassKoboldBottomTouched := TRUE;
END_IF;

// 3. Instance FB_DiveSearch (Recherche de fond Kobold)
// Interface refactorée en bus struct : remplissage champ par champ du bus d'entrée
// (CODESYS 3.5 refuse l'init anonyme en appel), puis passage via Inputs := DiveSearchInputs.
DiveSearchInputs.PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI;
DiveSearchInputs.Mode                  := instModes.Auth.Mode;
DiveSearchInputs.MotionRequestActive   := WinchBothMotionActive;
DiveSearchInputs.MotionDirection       := WinchBothMotionDirection;
DiveSearchInputs.BucketIsOpen          := PRG_04_Treuils_Benne.Data.BucketState.MechState.IsOpen;
DiveSearchInputs.KoboldImmersed        := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI;
DiveSearchInputs.M1Position_M          := PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM;
DiveSearchInputs.M2Position_M          := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM;
DiveSearchInputs.PositionsValid        := NOT PRG_02_Acquisition.Data.EncoderM1.EncoderFault
                                          AND NOT PRG_02_Acquisition.Data.EncoderM2.EncoderFault;
// Palier actuel M1 reellement commande (public PRG_04 §8). PRG_03 est de rang 03,
// PRG_04 de rang 04 : lecture du scan PRECEDENT (lag 1 scan assume, meme pratique que
// le reste de PRG_03). Rend effectif le refus interne du Palier 5 en plongee Kobold.
DiveSearchInputs.CurrentSpeedStep      := PRG_04_Treuils_Benne.Data.WinchM1State.StepNumber;
DiveSearchInputs.DiveStartMin_M        := GVL_IHM.CycleDiveSearch.Cfg.DiveStartMin_M;
DiveSearchInputs.ImmersionUpper_M      := GVL_IHM.CycleDiveSearch.Cfg.ImmersionUpper_M;
DiveSearchInputs.ImmersionLower_M      := GVL_IHM.CycleDiveSearch.Cfg.ImmersionLower_M;
DiveSearchInputs.CableLimitAscent_M    := GVL_IHM.Commun.Cfg.CfgCableLimitAscent_M;
DiveSearchInputs.LimitLegalDepthMin_M  := GVL_IHM.Commun.Cfg.LimitLegalDepthMinAllowed_M;
// Plancher palier descente Kobold : débit minimal nécessaire au fonctionnement du Kobold.
DiveSearchInputs.CfgDiveFloorStep      := 4;
DiveSearchInputs.CycleTime             := T#10ms;
DiveSearchInputs.BypassPreconditions   := GVL_IHM.CycleDiveSearch.Cmd.TglBypassDiveSearchSequence;
// Config : defaults du DUT ST_fbDiveSearch_Config conserves (DiveSpeedMin_Mps=0.15,
// TimeoutMarginFactor=1.5, TimeoutMinCourse_M=1.0, TimeoutMaxCourse_M=200.0, SecToMs=1000.0).

instDiveSearch(
    Enable := (instModes.Auth.Mode = E_Mode.MAINT_N1 OR instModes.Auth.Mode = E_Mode.MAINT_N2)
              AND GVL_IHM.CycleDiveSearch.Cmd.TglEnableDiveSearch,
    Reset  := PRG_07_Supervision.FaultMachineReset_IHM,
    Inputs := DiveSearchInputs
);

// Synthèse de confirmation fond
BottomPositionConfirmed := instDiveSearch.Outputs.BottomTouchConfirmed OR ManualBottomPositionConfirmed OR BypassKoboldBottomTouched;

// 4. Instance FB_ExtractionAssist (Fermeture et décollage assisté)
instExtractionAssist(
    Enable := (instModes.Auth.Mode = E_Mode.MAINT_N1 OR instModes.Auth.Mode = E_Mode.MAINT_N2)
              AND GVL_IHM.CycleExtraction.Cmd.TglEnableExtractionSequence,
    Reset := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode := instModes.Auth.Mode,
    MotionRequestActive := WinchBothMotionActive,
    MotionDirection := WinchBothMotionDirection,
    BottomPositionConfirmed := BottomPositionConfirmed,
    BucketIsClosed := PRG_04_Treuils_Benne.Data.BucketState.MechState.IsClosed,
    BucketBusy := PRG_04_Treuils_Benne.Data.BucketBusy,
    BucketError := PRG_04_Treuils_Benne.Data.BucketError,
    WinchSyncError := PRG_04_Treuils_Benne.Data.WinchSyncError,
    M1Position_M := PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM,
    M2Position_M := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM,
    M1MeasuredSpeedValid := PRG_02_Acquisition.Data.EncoderM1.Measurement.SpeedValid,
    M2MeasuredSpeedValid := PRG_02_Acquisition.Data.EncoderM2.Measurement.SpeedValid,
    PositionsValid := NOT PRG_02_Acquisition.Data.EncoderM1.EncoderFault
                       AND NOT PRG_02_Acquisition.Data.EncoderM2.EncoderFault,
    ControlAscentDistance_M := GVL_IHM.CycleExtraction.Cfg.ExtractionControlDistance_M,
    CfgBucketCloseTimeout := T#75s,
    BucketMoveTimeout := GVL_IHM.M2TreuilBenne.Bucket.Cfg.CfgTimeoutDuration,
    CycleTime := T#10ms
);

IF instExtractionAssist.BottomConfirmationConsumed THEN
    GVL_IHM.CycleDiveSearch.Cmd.TglBucketAtBottomConfirmed := FALSE;
END_IF;

{endregion}


// === 🔄 §3 SÉQUENCEUR DE CYCLE SEMI-AUTOMATIQUE ===
{region "§3 Séquenceur de cycle"}
// 🕹️ JoystickDeflected = manche défléchi (non centré) — D2
// ⚠️ Entrées consommées sur les bus publics Data (retard N-1 admis AF-02) :

instCycleSemiAuto(
    Enable                  := (instModes.Auth.Mode = E_Mode.SEMI_AUTO),
    Reset                   := GVL_IHM.Cycle.Cmd.BtnReset,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    EncoderFaultPresent     := (PRG_02_Acquisition.HwIn.Winch.COD1_DeviceState <> DEVICE_STATE.RUNNING) OR (PRG_02_Acquisition.HwIn.Winch.COD2_DeviceState <> DEVICE_STATE.RUNNING),
    Mode                    := instModes.Auth.Mode,
    JoystickDeflected       := NOT PRG_02_Acquisition.Data.Joystick.AtNeutralXY,
    DeadmanArmed            := PRG_02_Acquisition.Data.Joystick.DeadmanArmed,
    HeartbeatIhmOk          := GVL_IHM.Commun.HeartbeatIhmOk,
    StartCycle              := GVL_IHM.Cycle.Cmd.BtnStart,
    AbortCycle              := GVL_IHM.Cycle.Cmd.BtnAbort,
    SelTarget               := GVL_IHM.TranslationM3.Cmd.SelTarget,
    SetDepthM               := GVL_IHM.Cycle.Cfg.SetDepth_M,
    SetOffsetM              := GVL_IHM.Cycle.Cfg.SetOffset_M,
    KoboldContactFond       := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI,
    KoboldImmersed          := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI, // DI brut Kobold (fronts AX6/AX7) - convention a confirmer au banc
    KoboldContactorFeedback := TRUE, // TODO banc : cabler le retour contacteur Kobold reel ; TRUE = init reputee OK (verif AX5 dormante)
    LimitLegalReached       := GVL_IHM.Commun.LimitLegalReached,
    LimitLegalDepthM        := _CommunCfgPersist.LimitLegalDepthMinAllowed_M,
    WinchSyncError          := PRG_04_Treuils_Benne.Data.WinchSyncError,
    WinchSyncDeltaM         := PRG_04_Treuils_Benne.Data.WinchSyncSignedDeltaPosM,
    M1_CablePosM            := PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM,
    M2_CablePosM            := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM,
    M1_MeasuredSpeedMps     := PRG_02_Acquisition.Data.EncoderM1.Measurement.Speed_Mps,
    M2_MeasuredSpeedMps     := PRG_02_Acquisition.Data.EncoderM2.Measurement.Speed_Mps,
    SpeedMismatchThresholdMps := 1.5,   // Seuil écart vitesse M1/M2 (revue : ~1-2 m/s, retenu 1.5)
    SpeedMismatchTimeout    := T#500ms, // Tempo confirmation écart vitesse (revue)
    CableLimitM1AscentM     := _CommunCfgPersist.CfgCableLimitAscent_M,
    Translation_At_P1       := PRG_05_Translation.Data.M3_AtP1Stable,
    Translation_At_Tremie   := PRG_05_Translation.Data.M3_AtTremieStable,
    Translation_At_Maintenance := PRG_05_Translation.Data.M3_AtMaintenanceStable,
    Translation_Busy        := PRG_05_Translation.Data.TranslationBusy,
    Translation_Done        := PRG_05_Translation.Data.TranslationDone,
    Benne_Busy              := PRG_04_Treuils_Benne.Data.BucketBusy,
    Benne_Done              := PRG_04_Treuils_Benne.Data.BucketDone,
    Benne_IsOpen            := PRG_04_Treuils_Benne.Data.BucketState.MechState.IsOpen,
    Benne_IsClosed          := PRG_04_Treuils_Benne.Data.BucketState.MechState.IsClosed,
    Benne_IsRoughlyClosed   := PRG_04_Treuils_Benne.Data.Benne_IsRoughlyClosed,  // Tolérance matière 2m
    HomedM1                 := PRG_02_Acquisition.Data.EncoderM1.Homed,
    HomedM2                 := PRG_02_Acquisition.Data.EncoderM2.Homed,
    TopPositionSensor       := NOT PRG_02_Acquisition.HwIn.Winch.M1M2_TopPositionFree_DI,
    InitPositionOk          := CycleInitPositionOk,
    WinchesAtTopWindow      := CycleWinchesAtTopOk,
    HomingRequest           := GVL_IHM.M1TreuilRetenue.Cmd.BtnHome OR GVL_IHM.M2TreuilBenne.Cmd.BtnHome,
    CfgDrainTime            := GVL_IHM.Cycle.Cfg.DrainTime,
    SkipDrainRequest        := GVL_IHM.Cycle.Cmd.BtnSkipDrain,
    RepositionRequest       := GVL_IHM.Cycle.Cmd.BtnReposition,
    // Config diving / extraction (GEL 2026-09-03)
    DiveStartMinM           := GVL_IHM.CycleDiveSearch.Cfg.DiveStartMin_M, // altimetrie lancement Kobold (AT4)
    CfgRaiseOffBottomM      := GVL_IHM.Cycle.Cfg.RaiseOffBottom_M,   // GEL Q16 : decollement du fond AX8 (reglable IHM)
    CfgCtrlAscentMaxStep    := GVL_IHM.Cycle.Cfg.CtrlAscentMaxStep,  // GEL Q16 : palier max montee controle AX11 [1..2]
    M1_SpeedStepApplied     := PRG_04_Treuils_Benne.Data.WinchM1State.StepNumber, // palier applique (0..5) : garde palier<>4 en plongee (GT-dive-retry) + cause 8 (palier 5)
    M2_SpeedStepApplied     := PRG_04_Treuils_Benne.Data.WinchM2State.StepNumber,
    SampleCount            := _CycleSampleCount
);

{endregion}


// === 📤 §4 PUBLICATION DU BUS INTER-PRG & AUTORISATIONS ===
{region "§4 Publication bus public"}

// 1. Autorisations machine
Data.Auth := instModes.Auth;
// 1bis. Défauts de l'arbitre de mode (refus Semi-Auto, changement de mode refusé) —
// publiés pour que l'IHM les affiche : un interlock invisible est un interlock contourné.
Data.ModesFault := instModes.Fault;

// 1bis. Intention both continue opérateur (inconditionnelle, TOUS modes) — source unique
Data.WinchBothIntent.Active    := WinchBothMotionActive;
Data.WinchBothIntent.ReqAscent  := WinchBothMotionDirection > 0;
Data.WinchBothIntent.ReqDescend := WinchBothMotionDirection < 0;

// 2. Demandes programme et état public de séquence
IF instModes.Auth.Mode = E_Mode.SEMI_AUTO THEN
    // Demandes treuils M1 / M2 — copie struct entière : FB_CycleSemiAuto produit directement
    // le type de contrat inter-PRG (ST_Program*Request). Plus de re-mapping
    // champ-à-champ ni de DUT ST_fbCycle_*CmdDemand redondants (NC-090).
    Data.ReqProgram.ReqWinchM1 := instCycleSemiAuto.WinchM1Cmd;
    Data.ReqProgram.ReqWinchM2 := instCycleSemiAuto.WinchM2Cmd;

    // Demande translation M3
    Data.ReqProgram.ReqTranslation := instCycleSemiAuto.TranslationCmd;

    // Demande benne — FB_CycleSemiAuto fournit aussi les champs assistants neutres
    // (DescendPermitDiveBucketOpen=TRUE, ExtractionControlActive=FALSE, AscentPermit=FALSE, MinStepDown=0).
    Data.ReqProgram.ReqBucket := instCycleSemiAuto.BucketCmd;

    // État séquence active
    IF instCycleSemiAuto.Lifecycle.Busy THEN
        Data.SequenceState.SequenceId := E_ProgramSequence.MAIN_CYCLE;
    ELSE
        Data.SequenceState.SequenceId := E_ProgramSequence.NONE;
    END_IF;

    Data.SequenceState.Ready                  := instCycleSemiAuto.Ready;
    Data.SequenceState.Lifecycle              := instCycleSemiAuto.Lifecycle;
    Data.SequenceState.Fault                  := instCycleSemiAuto.Fault;
    Data.SequenceState.Step                   := instCycleSemiAuto.CycleStep;
    Data.SequenceState.StepStr                := instCycleSemiAuto.CycleStateStr;
    Data.SequenceState.StepAtFault            := instCycleSemiAuto.CycleStepAtError;
    Data.SequenceState.OperatorActionId       := instCycleSemiAuto.OperatorActionId;
    Data.SequenceState.OperatorAction         := instCycleSemiAuto.OperatorAction;
    Data.SequenceState.ExpectedAxis           := instCycleSemiAuto.ExpectedAxis;
    Data.SequenceState.ExpectedDirection      := instCycleSemiAuto.ExpectedDirection;
    Data.SequenceState.WaitingForOperator     := instCycleSemiAuto.WaitingForOperator;
    Data.SequenceState.WaitingForProcess      := instCycleSemiAuto.WaitingForProcess;
    Data.SequenceState.RequestActive          := instCycleSemiAuto.RequestActive;
    Data.SequenceState.SpeedMismatchMps       := instCycleSemiAuto.SpeedMismatchMps;
    Data.SequenceState.SpeedMismatchActive    := instCycleSemiAuto.SpeedMismatchActive;
    Data.SequenceState.SpeedMismatchConfirmed := instCycleSemiAuto.SpeedMismatchConfirmed;
    Data.SequenceState.CurrentCycleElapsed    := instCycleSemiAuto.CurrentCycleElapsed;
    Data.SequenceState.LastCycleDuration      := instCycleSemiAuto.LastCycleDuration;
    Data.SequenceState.DiveState              := E_DiveSearchState.WAIT_PRECONDITIONS;
    Data.SequenceState.DiveStepAtFault        := E_DiveSearchState.WAIT_PRECONDITIONS;
    Data.SequenceState.BottomTouchConfirmed   := FALSE;
    Data.SequenceState.ExtractionState        := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
    Data.SequenceState.ExtractionStepAtFault  := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;

    // === RESET ÉTATS ASSISTANTS (neutralisation déterministe au passage SEMI_AUTO) ===
    // Aucun assistant de dragage n'est actif en SEMI_AUTO : mêmes valeurs neutres que la branche DISABLE.
    Data.SequenceState.DiveReady                  := FALSE;
    Data.SequenceState.DiveBusy                   := FALSE;
    Data.SequenceState.DiveDone                   := FALSE;
    Data.SequenceState.DiveError                  := FALSE;
    Data.SequenceState.DiveErrorId                := 0;
    Data.SequenceState.ExtractionReady             := FALSE;
    Data.SequenceState.ExtractionBusy              := FALSE;
    Data.SequenceState.ExtractionDone              := FALSE;
    Data.SequenceState.ExtractionError             := FALSE;
    Data.SequenceState.ExtractionErrorId           := 0;
    Data.SequenceState.DumpAtTremieArmed           := FALSE;
    Data.SequenceState.DumpAtTremieAssistActive      := FALSE;
    Data.SequenceState.DumpAtTremieAtTremie          := FALSE;
    Data.SequenceState.DumpAtTremieBucketOpenArmed   := FALSE;
    Data.SequenceState.DumpAtTremieDescentLocked     := FALSE;
    Data.SequenceState.BypassDiveActive            := FALSE;
    Data.SequenceState.BypassKoboldBottomTouched   := FALSE;

ELSIF (instModes.Auth.Mode = E_Mode.MAINT_N1 OR instModes.Auth.Mode = E_Mode.MAINT_N2) THEN
    // Mode Manuel / Maintenance : Publication des requêtes issues des assistants
    Data.ReqProgram.ReqWinchM1.RunRequest := FALSE;
    Data.ReqProgram.ReqWinchM1.ReqAscent := FALSE;
    Data.ReqProgram.ReqWinchM1.ReqDescend := FALSE;
    Data.ReqProgram.ReqWinchM1.StepTgt  := 0;

    Data.ReqProgram.ReqWinchM2.RunRequest := FALSE;
    Data.ReqProgram.ReqWinchM2.ReqAscent := FALSE;
    Data.ReqProgram.ReqWinchM2.ReqDescend := FALSE;
    Data.ReqProgram.ReqWinchM2.StepTgt  := 0;

    // Cycle de homing machine (MAINT_N2 uniquement) : route ses ordres treuil couple
    // M1+M2 palier 1 (HX2 montee / HX3 descente). Le FB gate deja sur permis operateur
    // maintenu (homme-mort + joystick) et ne commande qu'en HX2/HX3 ; PRG_04 conserve
    // ses interlocks maintenance. Copie struct entiere (ST_ProgramWinchRequest).
    IF instModes.Auth.Mode = E_Mode.MAINT_N2
       AND PRG_02_Acquisition.Data.MachineHoming.Active THEN
        Data.ReqProgram.ReqWinchM1 := PRG_02_Acquisition.Data.MachineHoming.CmdWinchM1;
        Data.ReqProgram.ReqWinchM2 := PRG_02_Acquisition.Data.MachineHoming.CmdWinchM2;
    END_IF;

    Data.ReqProgram.ReqTranslation.ReqStart    := FALSE;
    Data.ReqProgram.ReqTranslation.PositionTgt := 0;

    // Requêtes benne et assistants
    DumpAtTremieActive := GVL_IHM.CycleDumpAtTremie.Cmd.TglEnableDumpAtTremie;
    DumpAtTremieAssistActive := DumpAtTremieActive;
    DumpAtTremieBucketOpenArmed := DumpAtTremieAssistActive AND PRG_05_Translation.Data.M3_AtTremieStable;

    Data.ReqProgram.ReqBucket.ReqOpen                     := DumpAtTremieBucketOpenArmed;
    Data.ReqProgram.ReqBucket.ReqClose                    := instExtractionAssist.BucketCloseRequest;
    // Contacteur Kobold : sortie FB_DiveSearch consommee (plus de recalcul inline).
    Data.ReqProgram.ReqBucket.ReqKoboldMeasureEnable      := instDiveSearch.Outputs.KoboldContactorCmd
                                                            OR (GVL_IHM.CycleDiveSearch.Cmd.TglBypassDiveSearchSequence
                                                                AND WinchBothMotionActive AND (WinchBothMotionDirection = -1));
    // Permis de descente plongee : sortie FB_DiveSearch consommee. Hors plongee (Enable=FALSE),
    // la descente reste libre ; pendant la plongee, elle n'est autorisee que si l'assistant la
    // delivre (Outputs.DescendPermit, qui integre la precondition benne ouverte).
    Data.ReqProgram.ReqBucket.DescendPermitDiveBucketOpen := (NOT instDiveSearch.Enable) OR instDiveSearch.Outputs.DescendPermit;
    Data.ReqProgram.ReqBucket.ExtractionControlActive     := instExtractionAssist.ExtractionControlActive;
    // Permis de remontee assistee : sortie FB_ExtractionAssist consommee (PRG_04 §5).
    Data.ReqProgram.ReqBucket.AscentPermit                := instExtractionAssist.AscentPermit;
    // Plancher de plongee : produit par FB_DiveSearch, consomme par PRG_04 §5ter.
    Data.ReqProgram.ReqBucket.MinStepDown                 := instDiveSearch.Outputs.MinStepDown;

    // Cycle de homing machine (MAINT_N2) : ordres benne palier 1 sans FDC soft (HX4).
    // Mutuellement exclusifs cote FB. Route OVERRIDE (pas un OR) quand le cycle homing est
    // engage : evite le cumul ReqOpen+ReqClose si un assistant (DumpAtTremie / Extraction)
    // etait actif au meme instant. Hors cycle homing : demandes assistants inchangees.
    IF instModes.Auth.Mode = E_Mode.MAINT_N2
       AND PRG_02_Acquisition.Data.MachineHoming.Active THEN
        Data.ReqProgram.ReqBucket.ReqOpen  := PRG_02_Acquisition.Data.MachineHoming.CmdBucketOpen;
        Data.ReqProgram.ReqBucket.ReqClose := PRG_02_Acquisition.Data.MachineHoming.CmdBucketClose;
    END_IF;

    // États de séquence
    IF instDiveSearch.Lifecycle.Busy THEN
        Data.SequenceState.SequenceId        := E_ProgramSequence.DIVE_SEARCH;
        Data.SequenceState.OperatorActionId  := instDiveSearch.Outputs.OperatorActionId;
        Data.SequenceState.OperatorAction    := instDiveSearch.Outputs.OperatorAction;
    ELSIF instExtractionAssist.Lifecycle.Busy THEN
        Data.SequenceState.SequenceId        := E_ProgramSequence.EXTRACTION;
        Data.SequenceState.OperatorActionId  := instExtractionAssist.OperatorActionId;
        Data.SequenceState.OperatorAction    := instExtractionAssist.OperatorAction;
    ELSE
        Data.SequenceState.SequenceId        := E_ProgramSequence.NONE;
        Data.SequenceState.OperatorActionId  := 0;
        Data.SequenceState.OperatorAction    := '';
    END_IF;

    Data.SequenceState.Ready                  := instDiveSearch.Ready OR instExtractionAssist.Ready;
    Data.SequenceState.Lifecycle.Busy         := instDiveSearch.Lifecycle.Busy OR instExtractionAssist.Lifecycle.Busy;
    Data.SequenceState.Lifecycle.Done         := instDiveSearch.Lifecycle.Done OR instExtractionAssist.Lifecycle.Done;
    Data.SequenceState.Fault.Error            := instDiveSearch.Fault.Error OR instExtractionAssist.Fault.Error;
    IF instDiveSearch.Fault.Error THEN
        Data.SequenceState.Fault.ErrorId      := instDiveSearch.Fault.ErrorId;
        Data.SequenceState.Fault.Latched      := instDiveSearch.Fault.Latched;
    ELSIF instExtractionAssist.Fault.Error THEN
        Data.SequenceState.Fault.ErrorId      := instExtractionAssist.Fault.ErrorId;
        Data.SequenceState.Fault.Latched      := instExtractionAssist.Fault.Latched;
    ELSE
        Data.SequenceState.Fault.ErrorId      := 0;
        Data.SequenceState.Fault.Latched      := FALSE;
    END_IF;
    Data.SequenceState.Step                   := E_AutoCycleStep.AX0_REPOS;
    Data.SequenceState.StepStr                := 'ASSIST_MODE';
    Data.SequenceState.StepAtFault            := E_AutoCycleStep.AX0_REPOS;
    Data.SequenceState.ExpectedAxis           := E_OperatorAxis.JOYSTICK_Y;
    Data.SequenceState.ExpectedDirection      := WinchBothMotionDirection;
    Data.SequenceState.WaitingForOperator     := FALSE;
    Data.SequenceState.WaitingForProcess      := FALSE;
    Data.SequenceState.RequestActive          := WinchBothMotionActive;
    Data.SequenceState.SpeedMismatchMps       := 0.0;
    Data.SequenceState.SpeedMismatchActive    := FALSE;
    Data.SequenceState.SpeedMismatchConfirmed := FALSE;
    Data.SequenceState.CurrentCycleElapsed    := T#0s;
    Data.SequenceState.LastCycleDuration      := T#0s;
    Data.SequenceState.DiveReady                  := instDiveSearch.Ready;
    Data.SequenceState.DiveBusy                   := instDiveSearch.Lifecycle.Busy;
    Data.SequenceState.DiveDone                   := instDiveSearch.Lifecycle.Done;
    Data.SequenceState.DiveError                  := instDiveSearch.Fault.Error;
    Data.SequenceState.DiveErrorId                := instDiveSearch.Fault.ErrorId;
    Data.SequenceState.DiveState                  := instDiveSearch.Outputs.StepState;
    Data.SequenceState.DiveStepAtFault             := instDiveSearch.Outputs.StepAtFault;
    Data.SequenceState.BottomTouchConfirmed       := BottomPositionConfirmed;
    Data.SequenceState.ExtractionReady             := instExtractionAssist.Ready;
    Data.SequenceState.ExtractionBusy              := instExtractionAssist.Lifecycle.Busy;
    Data.SequenceState.ExtractionDone              := instExtractionAssist.Lifecycle.Done;
    Data.SequenceState.ExtractionError             := instExtractionAssist.Fault.Error;
    Data.SequenceState.ExtractionErrorId           := instExtractionAssist.Fault.ErrorId;
    Data.SequenceState.ExtractionState             := instExtractionAssist.ExtractionState;
    Data.SequenceState.ExtractionStepAtFault       := instExtractionAssist.StepAtFault;
    Data.SequenceState.DumpAtTremieArmed           := DumpAtTremieActive;
    Data.SequenceState.DumpAtTremieAssistActive      := DumpAtTremieAssistActive;
    Data.SequenceState.DumpAtTremieAtTremie          := PRG_05_Translation.Data.M3_AtTremieStable;
    Data.SequenceState.DumpAtTremieBucketOpenArmed   := DumpAtTremieBucketOpenArmed;
    // Verrou descente treuil = GENERAL en MAINT (plus seulement pendant l'assist vidage) :
    // descente M1/M2 interdite tant que le pont M3 n'est pas ARRETE STABLE a P1 (travail)
    // ou a Maintenance. En transit / PV / P2 / Tremie -> pas de paye de cable. Echappatoire
    // MES : bypass FdC M3 (LimitSwitch) ou bypass global M3.
    // Position de travail = STATIQUE (mot capteurs M3), pas le jeton de franchissement :
    // au boot PLC, pont deja pose a P1/Maintenance -> descente autorisee sans devoir
    // franchir un capteur d'abord (M3_AtWorkPositionStable couvre M3_AtP1/Maint jetons
    // + lecture directe mot 00011 / 00000).
    Data.SequenceState.DumpAtTremieDescentLocked     :=
        NOT PRG_05_Translation.Data.M3_AtWorkPositionStable
        AND NOT GVL_IHM.TranslationM3.Bypass.LimitSwitch
        AND NOT GVL_IHM.TranslationM3.Bypass.Global;
    Data.SequenceState.BypassDiveActive            := GVL_IHM.CycleDiveSearch.Cmd.TglBypassDiveSearchSequence;
    Data.SequenceState.BypassKoboldBottomTouched   := BypassKoboldBottomTouched;

ELSE
    // Neutralisation déterministe (DISABLE)
    Data.ReqProgram.ReqWinchM1.RunRequest := FALSE;
    Data.ReqProgram.ReqWinchM1.ReqAscent := FALSE;
    Data.ReqProgram.ReqWinchM1.ReqDescend := FALSE;
    Data.ReqProgram.ReqWinchM1.StepTgt  := 0;

    Data.ReqProgram.ReqWinchM2.RunRequest := FALSE;
    Data.ReqProgram.ReqWinchM2.ReqAscent := FALSE;
    Data.ReqProgram.ReqWinchM2.ReqDescend := FALSE;
    Data.ReqProgram.ReqWinchM2.StepTgt  := 0;

    Data.ReqProgram.ReqTranslation.ReqStart    := FALSE;
    Data.ReqProgram.ReqTranslation.PositionTgt := 0;

    Data.ReqProgram.ReqBucket.ReqOpen                     := FALSE;
    Data.ReqProgram.ReqBucket.ReqClose                    := FALSE;
    Data.ReqProgram.ReqBucket.ReqKoboldMeasureEnable      := FALSE;
    Data.ReqProgram.ReqBucket.DescendPermitDiveBucketOpen := TRUE;
    Data.ReqProgram.ReqBucket.ExtractionControlActive     := FALSE;
    Data.ReqProgram.ReqBucket.AscentPermit                := FALSE;
    // DISABLE : plancher neutre (0 = aucun).
    Data.ReqProgram.ReqBucket.MinStepDown                 := 0;

    Data.SequenceState.SequenceId              := E_ProgramSequence.NONE;
    Data.SequenceState.Ready                   := FALSE;
    Data.SequenceState.Lifecycle.Busy          := FALSE;
    Data.SequenceState.Lifecycle.Done          := FALSE;
    Data.SequenceState.Fault.Error             := FALSE;
    Data.SequenceState.Fault.ErrorId           := 0;
    Data.SequenceState.Fault.Latched           := FALSE;
    Data.SequenceState.Step                    := E_AutoCycleStep.AX0_REPOS;
    Data.SequenceState.StepStr                 := 'AX0_REPOS';
    Data.SequenceState.StepAtFault             := E_AutoCycleStep.AX0_REPOS;
    Data.SequenceState.OperatorActionId        := 0;
    Data.SequenceState.OperatorAction          := '';
    Data.SequenceState.ExpectedAxis            := E_OperatorAxis.NONE;
    Data.SequenceState.ExpectedDirection       := 0;
    Data.SequenceState.WaitingForOperator      := FALSE;
    Data.SequenceState.WaitingForProcess       := FALSE;
    Data.SequenceState.RequestActive           := FALSE;
    Data.SequenceState.SpeedMismatchMps        := 0.0;
    Data.SequenceState.SpeedMismatchActive     := FALSE;
    Data.SequenceState.SpeedMismatchConfirmed  := FALSE;
    Data.SequenceState.CurrentCycleElapsed     := T#0s;
    Data.SequenceState.LastCycleDuration       := T#0s;
    Data.SequenceState.DiveReady                  := FALSE;
    Data.SequenceState.DiveBusy                   := FALSE;
    Data.SequenceState.DiveDone                   := FALSE;
    Data.SequenceState.DiveError                  := FALSE;
    Data.SequenceState.DiveErrorId                := 0;
    Data.SequenceState.DiveState                  := E_DiveSearchState.WAIT_PRECONDITIONS;
    Data.SequenceState.DiveStepAtFault            := E_DiveSearchState.WAIT_PRECONDITIONS;
    Data.SequenceState.BottomTouchConfirmed       := FALSE;
    Data.SequenceState.ExtractionReady             := FALSE;
    Data.SequenceState.ExtractionBusy              := FALSE;
    Data.SequenceState.ExtractionDone              := FALSE;
    Data.SequenceState.ExtractionError             := FALSE;
    Data.SequenceState.ExtractionErrorId           := 0;
    Data.SequenceState.ExtractionState             := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
    Data.SequenceState.ExtractionStepAtFault       := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
    Data.SequenceState.DumpAtTremieArmed           := FALSE;
    Data.SequenceState.DumpAtTremieAssistActive      := FALSE;
    Data.SequenceState.DumpAtTremieAtTremie          := FALSE;
    Data.SequenceState.DumpAtTremieBucketOpenArmed   := FALSE;
    Data.SequenceState.DumpAtTremieDescentLocked     := FALSE;
    Data.SequenceState.BypassDiveActive            := FALSE;
    Data.SequenceState.BypassKoboldBottomTouched   := FALSE;
END_IF;

{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut"}
// 🔑 1. FRONTS ET CAUSES
ResetEdge(CLK := Reset);
StartEdge(CLK := StartCycle);
DeadmanArmedEdge(CLK := DeadmanArmed);
AbortEdge(CLK := AbortCycle);
SkipDrainEdge(CLK := SkipDrainRequest);
KoboldRiseEdge(CLK := KoboldImmersed);
KoboldFallEdge(CLK := KoboldImmersed);
JoyDeflectedEdge(CLK := JoystickDeflected);

// Config diving/extraction bornee (repli defaut interne si non reglee / valeur implausible).
// DiveStartMinM = altimetrie de lancement Kobold dans le referentiel M1_CablePosM
// (positif, ~7,5 m au FDC haut, decroissant a la descente). Plage plausible 0,5..8,0 m ;
// hors plage -> repli 4,0 m.
IF (DiveStartMinM >= 0.5) AND (DiveStartMinM <= 8.0) THEN
    DiveStartMinEff := DiveStartMinM;
ELSE
    DiveStartMinEff := 4.0;
END_IF;
RaiseOffBottomEff := SEL(CfgRaiseOffBottomM > 0.0, CST_RaiseOffBottomDefaultM, CfgRaiseOffBottomM);
CtrlAscentMaxStepEff := LIMIT(1, CfgCtrlAscentMaxStep, 2);

// ⏱️ Chronomètre du cycle : compte tant que le séquenceur est actif (Lifecycle.Busy).
// .ET = durée écoulée du cycle en cours ; figée dans LastCycleDuration à l'achèvement (X13).
CycleRunTimer(IN := Lifecycle.Busy, PT := T#12h);
CurrentCycleElapsed := CycleRunTimer.ET;

// Durée d'égouttage effective : config IHM si valide, sinon défaut interne.
DrainTimeEff := SEL(CfgDrainTime <= T#0s, CfgDrainTime, DrainingTime);

// ⏱️ Surveillance indépendante de la remontée lente de controle
// AX11_CTRL_ASCENT -> AX12_LOADED_ASCENT : TON de stabilisation palier lent.
StabilizationTimer(IN := (State = E_AutoCycleStep.AX11_CTRL_ASCENT), PT := CtrlAscentTimeout);

// ⏱️ AX5_KOBOLD_INIT : fenetre de confirmation du retour contacteur Kobold.
KoboldInitTimer(IN := (State = E_AutoCycleStep.AX5_KOBOLD_INIT), PT := CST_KoboldInitTimeout);

// 📏 Comparaison vitesse réelle M1/M2
SpeedMismatchMps := ABS(M1_MeasuredSpeedMps - M2_MeasuredSpeedMps);
SpeedMismatchActive := (State = E_AutoCycleStep.AX11_CTRL_ASCENT)
                       AND JoystickDeflected
                       AND (SpeedMismatchThresholdMps > 0.0)
                       AND (SpeedMismatchTimeout > T#0ms)
                       AND (SpeedMismatchMps > SpeedMismatchThresholdMps);
// AX11_CTRL_ASCENT -> AX_STAB : TON confirmation écart vitesse.
SpeedMismatchTimer(IN := SpeedMismatchActive, PT := SpeedMismatchTimeout);
SpeedMismatchConfirmed := SpeedMismatchTimer.Q;

// Tempo max d'étape (R5) — backstop durée d'état, lancé SEULEMENT si pilotage joystick actif.
// Xi -> AX_STAB sur dépassement. Réarmé à CHAQUE changement d'étape (IN=FALSE 1 scan) :
// chaque étape dispose de sa propre fenêtre StepMaxTimeout, la tempo n'est PAS cumulative
// sur l'ensemble du cycle (un cycle réel long ne tombe plus en AX_STAB intempestif).
StepMaxTimer(IN := (State = StepMaxPrevState)
                  AND JoystickDeflected
                  AND (State <> E_AutoCycleStep.AX0_REPOS)
                  AND (State <> E_AutoCycleStep.AX18_DONE_SYNC)
                  AND (State <> E_AutoCycleStep.AX_STAB)
                  AND (State <> E_AutoCycleStep.AX_DIVING_RETRY),
             PT := StepMaxTimeout);
StepMaxPrevState := State;

// Egouttage AX13 : TON gaté sur l'étape (remis à 0 hors AX13). Remplace l'ancien IN:=TRUE câblé
// qui pouvait laisser Q déjà vrai à l'entrée en AX13 (temps d'égouttage non respecté).
DrainingTimer(IN := (State = E_AutoCycleStep.AX13_DRAIN_PAUSE), PT := DrainTimeEff);

// GT-dive-retry (GEL Q11) : en AX5/AX6/AX7, erreur sequence Kobold (retour contacteur
// absent apres CST_KoboldInitTimeout) OU joystick relache (>= 200 ms, anti-rebond) OU
// palier applique <> 4 sur M1 ou M2 (feedback si cable) -> reprise AX_DIVING_RETRY
// (PAS un defaut latche).
RetryJoyReleaseTimer(IN := ((State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                             OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                             OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM))
                            AND NOT JoystickDeflected,
                     PT := T#200ms);
// Palier bloque SOUS 4 pendant la plongee : on TOLERE la rampe 1->4 (tempo contacteurs,
// GEL AX4) ; seul un blocage confirme > 4 s en AX5..AX7 declenche la reprise. Palier 5
// (> 4) est traite instantanement par la cause de defaut 8 (latche), pas ici.
PalierNot4Timer(IN := ((State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                        OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                        OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM))
                       AND JoystickDeflected
                       AND ( ((M1_SpeedStepApplied > 0) AND (M1_SpeedStepApplied < CST_StepDive))
                          OR ((M2_SpeedStepApplied > 0) AND (M2_SpeedStepApplied < CST_StepDive)) ),
                PT := T#5s);
DivingRetryTrig := ((State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                     OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                     OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM))
                   AND ( (KoboldInitTimer.Q AND NOT KoboldContactorFeedback)
                         OR RetryJoyReleaseTimer.Q
                         OR PalierNot4Timer.Q );

// Table des causes de défaut
instCauses[0].Active   := LimitLegalReached
                          AND ((State = E_AutoCycleStep.AX4_DESCEND_DIVING)
                            OR (State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                            OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                            OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM));
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Limite legale de profondeur atteinte pendant descente';

instCauses[1].Active   := WinchSyncError AND (State <> E_AutoCycleStep.AX0_REPOS) AND (State <> E_AutoCycleStep.AX_STAB);
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Desynchronisme treuils M1/M2 bloquant';

instCauses[2].Active   := SpeedMismatchConfirmed AND (State <> E_AutoCycleStep.AX0_REPOS) AND (State <> E_AutoCycleStep.AX_STAB);
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Ecart de vitesse M1/M2 confirme en montee';

instCauses[3].Active   := NOT HeartbeatIhmOk AND (State <> E_AutoCycleStep.AX0_REPOS) AND (State <> E_AutoCycleStep.AX_STAB);
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Perte communication IHM pendant cycle';

instCauses[4].Active   := StepMaxTimer.Q AND (State <> E_AutoCycleStep.AX_STAB);
instCauses[4].Latching := TRUE;
instCauses[4].Texte    := 'Depassement tempo maximale d etape (blocage mouvement)';

instCauses[5].Active   := (StabilizationTimer.Q OR (ABS(M1_CablePosM - M2_CablePosM) > CtrlAscentToleranceM))
                          AND (State = E_AutoCycleStep.AX11_CTRL_ASCENT);
instCauses[5].Latching := TRUE;
instCauses[5].Texte    := 'Defaut de stabilisation / tolerance ecart codeurs en remontee controle';

// Backstop anti-telescopage : ecart de position M1/M2 excessif pendant une phase
// reellement couplee. AX11 a deja son propre controle (instCauses[5]). Seuil grossier
// (0,50 m) : filet local si FB_SyncDeviation (PRG_04) ne coupe pas.
instCauses[6].Active   := (ABS(M1_CablePosM - M2_CablePosM) > CST_CoupledPosBacklashM)
                          AND JoystickDeflected
                          AND ((State = E_AutoCycleStep.AX4_DESCEND_DIVING)
                            OR (State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                            OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                            OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM)
                            OR (State = E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM)
                            OR (State = E_AutoCycleStep.AX12_LOADED_ASCENT)
                            OR (State = E_AutoCycleStep.AX15C_DUMP_REPOSITION));
instCauses[6].Latching := TRUE;
instCauses[6].Texte    := 'Ecart de position M1/M2 excessif en phase couplee (anti-telescopage)';

// AX2 : pendant la translation vers P1 les treuils M1/M2 doivent RESTER au FDC
// logiciel haut (WinchesAtTopWindow, calcul PRG_03). S'ils quittent la fenetre
// -> defaut latche, sortie cycle (GEL SEMI_AUTO cause 7 / Q10).
instCauses[7].Active   := NOT WinchesAtTopWindow AND (State = E_AutoCycleStep.AX2_TRANSLATE_P1);
instCauses[7].Latching := TRUE;
instCauses[7].Texte    := 'Treuils M1/M2 hors FDC haut pendant la translation vers P1';

// GEL cause 8 : palier vitesse > 4 (palier 5) applique pendant la plongee. Le FB commande
// toujours CST_StepDive = 4 ; un palier 5 en retour feedback = anomalie aval -> defaut latche.
// (Un palier < 4 en retour est traite en reprise par GT-dive-retry, pas ici.)
instCauses[8].Active   := (((M1_SpeedStepApplied > CST_StepDive) OR (M2_SpeedStepApplied > CST_StepDive)))
                          AND ((State = E_AutoCycleStep.AX4_DESCEND_DIVING)
                            OR (State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                            OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                            OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM));
instCauses[8].Latching := TRUE;
instCauses[8].Texte    := 'Palier vitesse > 4 (palier 5) pendant la plongee - interdit';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
ErrorEdge(CLK := Fault.Error);
{endregion}

{region "§2 Gate securite & Bascule Mode"}
// 🛑 2. GATES DE SÉCURITÉ ET NEUTRALISATION
// Le mode SEMI_AUTO peut être sélectionné sous AU/défaut (FB_Modes), mais le cycle
// ne tourne JAMAIS sans puissance (PowerContactorEngaged) ni avec un codeur défaillant
// (EncoderFaultPresent) — les données de position invalides rendraient le Grafcet erroné.
IF NOT Enable OR NOT PowerContactorEngaged OR EncoderFaultPresent THEN
    WinchM1Cmd.RunRequest     := FALSE;
    WinchM1Cmd.ReqAscent      := FALSE;
    WinchM1Cmd.ReqDescend     := FALSE;
    WinchM1Cmd.StepTgt        := 0;

    WinchM2Cmd.RunRequest     := FALSE;
    WinchM2Cmd.ReqAscent      := FALSE;
    WinchM2Cmd.ReqDescend     := FALSE;
    WinchM2Cmd.StepTgt        := 0;

    TranslationCmd.ReqStart   := FALSE;
    TranslationCmd.PositionTgt  := 0;

    BucketCmd.ReqOpen         := FALSE;
    BucketCmd.ReqClose        := FALSE;
    BucketCmd.ReqKoboldMeasureEnable := FALSE;

    // Si on quitte le semi-auto alors qu'un cycle était en cours, on mémorise l'étape pour la pause
    IF (State <> E_AutoCycleStep.AX0_REPOS) AND (State <> E_AutoCycleStep.AX18_DONE_SYNC) AND (State <> E_AutoCycleStep.AX_STAB) THEN
        PausedState := State;
        WaitingResume := TRUE;
    END_IF;

    CycleStep            := State;
    CycleStateStr        := 'Cycle desactive : securite/codeur/mode';
    Ready                := FALSE;
    Lifecycle.Busy       := FALSE;
    Lifecycle.Done       := FALSE;
    SpeedMismatchTimer(IN := FALSE, PT := SpeedMismatchTimeout);
    SpeedMismatchMps := 0.0;
    SpeedMismatchActive := FALSE;
    SpeedMismatchConfirmed := FALSE;
    OperatorActionId := 0;
    IF EncoderFaultPresent THEN
        OperatorAction := 'Cycle non autorise : defaut codeur present. Reinitialiser le defaut codeur.';
    ELSE
        OperatorAction := 'Passer en mode Semi-Auto et engager la securite pour activer le cycle.';
    END_IF;
    ExpectedAxis := E_OperatorAxis.NONE;
    ExpectedDirection := 0;
    WaitingForOperator := FALSE;
    WaitingForProcess := FALSE;
    RequestActive := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;

// 🛡️ Gate continu homme-mort : le mouvement n'est autorisé que si le manche est
// défléchi (JoystickDeflected) ET l'homme-mort est armé (DeadmanArmed). Chaque
// commande de mouvement est gatée par ce permis à chaque scan (pas seulement au
// démarrage). Le séquenceur (transitions X0→X13) reste piloté par JoystickDeflected.
CycleMotionPermit := JoystickDeflected AND DeadmanArmed;

// Au retour en Semi-Auto, si une étape était en cours, on exige une reprise consciente
IF WaitingResume THEN
    // 🔒 Sécurité anti-redémarrage automatique (AF-04 §4.1) : le cycle ne reprend
    // PAS sur manche + homme-mort seuls. Il reste en attente d'un geste conscient
    // (StartCycle) avant de restaurer l'étape mémorisée.
    IF StartEdge.Q THEN
        State := PausedState;   // reprise consciente : restaure l'étape mémorisée
        WaitingResume := FALSE;
    ELSE
        // Hold : neutralise toute demande de mouvement et affiche l'attente.
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;
        TranslationCmd.ReqStart := FALSE; TranslationCmd.PositionTgt := 0;
        BucketCmd.ReqOpen := FALSE; BucketCmd.ReqClose := FALSE; BucketCmd.ReqKoboldMeasureEnable := FALSE;
        CycleStep := PausedState;
        CycleStateStr := 'Cycle en pause : reprise consciente requise (StartCycle)';
        Lifecycle.Busy := FALSE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.BUTTON;
        ExpectedDirection := 0;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#0400;
        OperatorAction := 'Reprendre le cycle : appuyer sur StartCycle (geste conscient).';
        RequestActive := FALSE;
    END_IF;
END_IF;

// 🧊 R9 — capture l'étape spécifique AVANT la bascule vers AX_STAB
IF ErrorEdge.Q THEN
    CycleStepAtError := State;
    State := E_AutoCycleStep.AX_STAB;
    WaitingResume := FALSE;   // un défaut abroge la reprise consciente : repli AX_STAB
END_IF;

// GT-dive-retry (GEL Q11) : reprise de plongee (PAS un defaut latche). Prioritaire
// apres le repli defaut : une vraie erreur (ErrorEdge) l'emporte.
IF DivingRetryTrig AND (State <> E_AutoCycleStep.AX_STAB) THEN
    State := E_AutoCycleStep.AX_DIVING_RETRY;
END_IF;

IF ResetEdge.Q THEN
    SavedState := E_AutoCycleStep.AX0_REPOS;
    BottomTouched := FALSE;
    IF State = E_AutoCycleStep.AX_STAB THEN
        State := E_AutoCycleStep.AX0_REPOS;
    END_IF;
END_IF;

// Gestion de l'Abandon explicite
IF AbortEdge.Q THEN
    State := E_AutoCycleStep.AX0_REPOS;
    WaitingResume := FALSE;
    PausedState := E_AutoCycleStep.AX0_REPOS;
END_IF;

// SEMI_AUTO : FB_CycleSemiAuto est le SEUL producteur des demandes benne. Les champs
// assistants (DiveSearch/ExtractionAssist) sont inactifs en cycle automatique
// -> valeurs neutres déterministes (identiques à la branche SEMI_AUTO de PRG_03).
BucketCmd.DescendPermitDiveBucketOpen := TRUE;
BucketCmd.ExtractionControlActive := FALSE;
BucketCmd.MinStepDown := 0;
{endregion}

{region "§3 Machine etat cycle automatique"}
// 🔁 2. LOGIQUE DU SÉQUENCEUR (Machine d'état) — CASE sur enum unique (R1)
// Pendant une reprise consciente (WaitingResume), le séquenceur est gelé :
// l'étape mémorisée ne s'exécute pas tant que StartCycle n'a pas été appuyé.
IF NOT WaitingResume THEN
CASE State OF

    E_AutoCycleStep.AX0_REPOS:
        CycleStep := E_AutoCycleStep.AX0_REPOS;
        CycleStateStr := 'AX0 - Verification coherence systeme';
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;
        TranslationCmd.ReqStart := FALSE; TranslationCmd.PositionTgt := 0;
        BucketCmd.ReqOpen := FALSE; BucketCmd.ReqClose := FALSE; BucketCmd.ReqKoboldMeasureEnable := FALSE;
        Lifecycle.Busy := FALSE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.BUTTON;
        ExpectedDirection := 0;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#0400;
        OperatorAction := 'AX0 - Demander le demarrage du cycle (Bouton IHM ou armement Homme-Mort).';
        SampleCountDone := FALSE;   // F2: réarmement du front de comptage à chaque entrée en X0
        BottomTouched   := FALSE;   // info fond touche effacee au repos

        // Transition si système sain et réarmé (front reset ou démarrage).
        // 🔫 D2 : démarrage par bouton IHM (StartEdge) OU armement homme-mort joystick
        IF (StartEdge.Q OR DeadmanArmedEdge.Q) AND NOT Fault.Latched THEN
            WaitingResume := FALSE;
            State := E_AutoCycleStep.AX1_INIT;
        END_IF;

    E_AutoCycleStep.AX1_INIT:
        CycleStep := E_AutoCycleStep.AX1_INIT;
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedDirection := 0;

        // AX1_INIT : verification des CONDITIONS INITIALES du cycle. AUCUN ordre de
        // mouvement, aucun referencement (datum M1/M2/benne = responsabilite exclusive
        // FB_CycleMachineHoming). Conditions : codeurs M1/M2 references, aucun defaut
        // latche, treuils au FDC logiciel haut (TopPositionSensor), et posture de depart
        // OK (InitPositionOk : chariot M3 PAS a droite de P1 + treuils dans la plage
        // +/- 0,4 m autour du FDC haut, calcul PRG_03 ; positionnement fin P1 = AX2).
        InitConditionsOk := HomedM1 AND HomedM2 AND NOT Fault.Latched
                            AND TopPositionSensor AND InitPositionOk;
        IF InitConditionsOk THEN
            CycleStateStr := 'AX1 - Conditions initiales OK';
            ExpectedAxis := E_OperatorAxis.NONE;
            WaitingForOperator := FALSE;
            WaitingForProcess := TRUE;
            OperatorActionId := 0;
            OperatorAction := '';
            State := E_AutoCycleStep.AX2_TRANSLATE_P1;   // franchie sans mouvement
        ELSIF NOT (HomedM1 AND HomedM2) THEN
            CycleStateStr := 'AX1 - Machine non referencee';
            ExpectedAxis := E_OperatorAxis.BUTTON;
            WaitingForOperator := TRUE;
            WaitingForProcess := FALSE;
            OperatorActionId := 16#0401;
            OperatorAction := 'AX1 - Machine non referencee : passer en maintenance pour le referencement.';
        ELSE
            CycleStateStr := 'AX1 - Conditions initiales non remplies';
            ExpectedAxis := E_OperatorAxis.BUTTON;
            WaitingForOperator := TRUE;
            WaitingForProcess := FALSE;
            OperatorActionId := 16#0401;
            OperatorAction := 'AX1 - Amener les treuils au FDC haut.';
        END_IF;

    E_AutoCycleStep.AX2_TRANSLATE_P1:
        CycleStep := E_AutoCycleStep.AX2_TRANSLATE_P1;
        CycleStateStr := 'AX2 - Mise en position P1 (translation)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_X;
        // GEL SEMI_AUTO Q10 : le cycle n'emet AUCUNE commande M3 automatique (pas de
        // selection de cible). L'operateur pousse le joystick VERS LA DROITE et amene M3
        // a P1 ; ralenti PV + arret sur FDC P1 assures par PRG_05/FB_Translation (comme en
        // maintenance). Le cycle SURVEILLE en permanence que les treuils M1/M2 RESTENT au
        // FDC logiciel haut (WinchesAtTopWindow) : sortie sur defaut latche (cause 7) sinon.
        // Le controle "chariot pas a droite de P1" est fait en AX1_INIT, pas ici.
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;
        TranslationCmd.PositionTgt := 3;          // repere P1 pour PRG_05 (info ; pas de pilotage cycle)

        IF Translation_At_P1 THEN
            ExpectedDirection := 0;
            WaitingForOperator := FALSE;
            WaitingForProcess := TRUE;
            OperatorActionId := 16#0402;
            OperatorAction := 'AX2 - Position P1 atteinte.';
            TranslationCmd.ReqStart := FALSE;
            State := E_AutoCycleStep.AX3_OPEN_BUCKET;
        ELSE
            // Entre tremie et P1 : l'operateur pousse le joystick VERS LA DROITE (axe
            // Tremie--P2--P1--Maintenance : P1 est a droite de la tremie). Maintien requis ;
            // ralenti PV + arret FDC P1 assures par PRG_05. Transition sur P1 STABILISE.
            ExpectedDirection := 1;
            WaitingForOperator := NOT JoystickDeflected;
            WaitingForProcess := JoystickDeflected;
            OperatorActionId := 16#0402;
            OperatorAction := 'AX2 - Pousser le joystick vers la droite : arret automatique sur P1.';
            TranslationCmd.ReqStart := CycleMotionPermit;
        END_IF;

    E_AutoCycleStep.AX3_OPEN_BUCKET:
        CycleStep := E_AutoCycleStep.AX3_OPEN_BUCKET;
        CycleStateStr := 'AX3 - Ouverture benne';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 0;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0403;
        OperatorAction := 'AX3 - Joystick pousse : ouverture benne jusqu au FDC logiciel benne ouverte.';

        // X3 = etape benne seule : treuils explicitement neutralises (config treuil unique par etape).
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;

        IF Benne_IsOpen THEN
            State := E_AutoCycleStep.AX4_DESCEND_DIVING;
        ELSE
            BucketCmd.ReqOpen := CycleMotionPermit;
            IF JoystickDeflected AND Benne_Done AND Benne_IsOpen THEN
                BucketCmd.ReqOpen := FALSE;
                State := E_AutoCycleStep.AX4_DESCEND_DIVING;
            END_IF;
        END_IF;

    (* ===================== DIVING (AX4..AX8 + AX_DIVING_RETRY) ===================== *)

    E_AutoCycleStep.AX4_DESCEND_DIVING:
        CycleStep := E_AutoCycleStep.AX4_DESCEND_DIVING;
        CycleStateStr := 'AX4 - Plongee couplee palier 4 jusqu a l altimetrie de lancement';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0404;
        OperatorAction := 'AX4 - Maintenir la descente palier 4 (Kobold pas encore enclenche).';

        // Palier 4 MINI ET MAXI (CST_StepDive), palier 5 interdit (cause 8). Tempo
        // sequencement contacteurs conservee en aval (PRG_04 : montee progressive 1->4).
        // Contacteur Kobold PAS enclenche a cette etape.
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := TRUE;
        WinchM1Cmd.StepTgt  := CST_StepDive;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := TRUE;
        WinchM2Cmd.StepTgt  := CST_StepDive;
        BucketCmd.ReqKoboldMeasureEnable := FALSE;

        // AT4 : altimetrie de lancement atteinte (M1 ET M2 <= DiveStartMinEff).
        IF JoystickDeflected
           AND (M1_CablePosM <= DiveStartMinEff) AND (M2_CablePosM <= DiveStartMinEff) THEN
            State := E_AutoCycleStep.AX5_KOBOLD_INIT;
        END_IF;

    E_AutoCycleStep.AX5_KOBOLD_INIT:
        CycleStep := E_AutoCycleStep.AX5_KOBOLD_INIT;
        CycleStateStr := 'AX5 - Activation contacteur Kobold au vol';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0405;
        OperatorAction := 'AX5 - Maintenir la descente palier 4 : initialisation Kobold en cours.';

        // Descente palier 4 maintenue ; enclenche le contacteur Kobold et attend le retour.
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := TRUE;
        WinchM1Cmd.StepTgt  := CST_StepDive;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := TRUE;
        WinchM2Cmd.StepTgt  := CST_StepDive;
        BucketCmd.ReqKoboldMeasureEnable := CycleMotionPermit;

        // AT5 : retour contacteur Kobold coherent -> recherche immersion.
        // (echec init / joystick relache / palier <> 4 -> AX_DIVING_RETRY via GT-dive-retry §1)
        IF JoystickDeflected AND KoboldContactorFeedback THEN
            State := E_AutoCycleStep.AX6_SEARCH_IMMERSION;
        END_IF;

    E_AutoCycleStep.AX6_SEARCH_IMMERSION:
        CycleStep := E_AutoCycleStep.AX6_SEARCH_IMMERSION;
        CycleStateStr := 'AX6 - Recherche entree dans l eau (front DI Kobold 0->1)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0406;
        OperatorAction := 'AX6 - Maintenir la descente palier 4 : entree dans l eau attendue.';

        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := TRUE;
        WinchM1Cmd.StepTgt  := CST_StepDive;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := TRUE;
        WinchM2Cmd.StepTgt  := CST_StepDive;
        BucketCmd.ReqKoboldMeasureEnable := CycleMotionPermit;

        // AT6 : front montant DI Kobold (immersion confirmee) -> recherche du fond.
        IF JoystickDeflected AND KoboldRiseEdge.Q THEN
            State := E_AutoCycleStep.AX7_SEARCH_BOTTOM;
        END_IF;

    E_AutoCycleStep.AX7_SEARCH_BOTTOM:
        CycleStep := E_AutoCycleStep.AX7_SEARCH_BOTTOM;
        CycleStateStr := 'AX7 - Recherche du fond (front DI Kobold 1->0)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0407;
        OperatorAction := 'AX7 - Maintenir la descente palier 4 sous l eau : detection du fond.';

        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := TRUE;
        WinchM1Cmd.StepTgt  := CST_StepDive;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := TRUE;
        WinchM2Cmd.StepTgt  := CST_StepDive;
        BucketCmd.ReqKoboldMeasureEnable := CycleMotionPermit;

        // AT7 : front descendant DI Kobold (ou retour dedie KoboldContactFond) = fond.
        IF JoystickDeflected AND (KoboldFallEdge.Q OR KoboldContactFond) THEN
            State := E_AutoCycleStep.AX8_BOTTOM_CONFIRMED;
        END_IF;

    E_AutoCycleStep.AX8_BOTTOM_CONFIRMED:
        CycleStep := E_AutoCycleStep.AX8_BOTTOM_CONFIRMED;
        CycleStateStr := 'AX8 - Fond confirme : coupure treuils, memorisation';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.NONE;
        ExpectedDirection := 0;
        WaitingForOperator := FALSE;
        WaitingForProcess := TRUE;
        OperatorActionId := 16#0408;
        OperatorAction := 'AX8 - Fond touche.';

        // Coupure INSTANTANEE de toutes les commandes treuils (meme scan) + Kobold coupe.
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;
        BucketCmd.ReqKoboldMeasureEnable := FALSE;

        TouchPositionM := M1_CablePosM;
        BottomTouched  := TRUE;   // variable d'info latchee (GEL AX8) - effacee a AX0 / AX_STAB / Reset
        IF LimitLegalDepthM < -0.01 THEN
            RaiseTargetM := MAX(TouchPositionM + RaiseOffBottomEff, LimitLegalDepthM + RaiseOffBottomEff);
        ELSE
            RaiseTargetM := TouchPositionM + RaiseOffBottomEff;
        END_IF;
        State := E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM;

    E_AutoCycleStep.AX_DIVING_RETRY:
        CycleStep := E_AutoCycleStep.AX_DIVING_RETRY;
        CycleStateStr := 'AX_DIVING_RETRY - Reprise plongee : remonter au FDC haut';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0481;
        OperatorAction := 'AX_DIVING_RETRY - Reprise plongee : monter jusqu au FDC haut, puis relancer.';

        // Remontee assistee palier lent, Kobold coupe.
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := TRUE; WinchM1Cmd.ReqDescend := FALSE;
        WinchM1Cmd.StepTgt  := CST_StepSlow;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := TRUE; WinchM2Cmd.ReqDescend := FALSE;
        WinchM2Cmd.StepTgt  := CST_StepSlow;
        BucketCmd.ReqKoboldMeasureEnable := FALSE;

        // AT-retry : treuils revenus au FDC haut -> nouvelle tentative de plongee.
        IF JoystickDeflected AND (WinchesAtTopWindow OR TopPositionSensor) THEN
            WinchM1Cmd.RunRequest := FALSE;
            WinchM2Cmd.RunRequest := FALSE;
            State := E_AutoCycleStep.AX4_DESCEND_DIVING;
        END_IF;

    (* ===================== EXTRACTION (AX9..AX12) ===================== *)

    E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM:
        CycleStep := E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM;
        CycleStateStr := 'AX9 - Retente les cables (palier 1), decollement du fond';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0409;
        OperatorAction := 'AX9 - Maintenir la montee palier 1 : retente des cables, decollement du fond.';

        // Palier 1 (doux). Selecteur couplage BOTH/M1/M2 = garde cote PRG_04 (GEL Q15),
        // le sequenceur commande toujours les deux treuils symetriquement.
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := TRUE; WinchM1Cmd.ReqDescend := FALSE;
        WinchM1Cmd.StepTgt := CST_StepSlow;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := TRUE; WinchM2Cmd.ReqDescend := FALSE;
        WinchM2Cmd.StepTgt := CST_StepSlow;

        IF JoystickDeflected AND (M1_CablePosM >= RaiseTargetM) AND (M2_CablePosM >= RaiseTargetM) THEN
            WinchM1Cmd.RunRequest := FALSE;
            WinchM2Cmd.RunRequest := FALSE;
            State := E_AutoCycleStep.AX10_CLOSE_BUCKET;
        END_IF;

    E_AutoCycleStep.AX10_CLOSE_BUCKET:
        CycleStep := E_AutoCycleStep.AX10_CLOSE_BUCKET;
        CycleStateStr := 'AX10 - Fermeture benne (tolerance a peu pres ferme)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040A;
        OperatorAction := 'AX10 - Maintenir la commande : fermeture de la benne.';

        // Etape benne seule : les DEUX treuils explicitement neutralises.
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;
        BucketCmd.ReqClose := CycleMotionPermit;

        IF JoystickDeflected AND (Benne_Done AND (Benne_IsClosed OR Benne_IsRoughlyClosed)) THEN
            BucketCmd.ReqClose := FALSE;
            // C1e (GEL principe 4) : AX10 -> AX11 sans temps mort. M1+M2 lances le MEME
            // scan que la sortie AX10_CLOSE_BUCKET (pas de creux RunRequest a la frontiere).
            WinchM1Cmd.RunRequest := CycleMotionPermit;
            WinchM1Cmd.ReqAscent := TRUE; WinchM1Cmd.ReqDescend := FALSE;
            WinchM1Cmd.StepTgt  := CtrlAscentMaxStepEff;
            WinchM2Cmd.RunRequest := CycleMotionPermit;
            WinchM2Cmd.ReqAscent := TRUE; WinchM2Cmd.ReqDescend := FALSE;
            WinchM2Cmd.StepTgt  := CtrlAscentMaxStepEff;
            State := E_AutoCycleStep.AX11_CTRL_ASCENT;
        END_IF;

    E_AutoCycleStep.AX11_CTRL_ASCENT:
        CycleStep := E_AutoCycleStep.AX11_CTRL_ASCENT;
        CycleStateStr := 'AX11 - Remontee lente de controle';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040B;
        OperatorAction := 'AX11 - Maintenir la montee de controle : palier et synchronisme.';

        // Palier max reglable IHM, borne [1..2] (defaut 1 / P1 ; P2 possible au besoin).
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := TRUE; WinchM1Cmd.ReqDescend := FALSE;
        WinchM1Cmd.StepTgt  := CtrlAscentMaxStepEff;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := TRUE; WinchM2Cmd.ReqDescend := FALSE;
        WinchM2Cmd.StepTgt  := CtrlAscentMaxStepEff;

        IF JoystickDeflected
           AND (M1_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (M2_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (ABS(M1_CablePosM - M2_CablePosM) <= CtrlAscentToleranceM) THEN
            State := E_AutoCycleStep.AX12_LOADED_ASCENT;
        END_IF;

    E_AutoCycleStep.AX12_LOADED_ASCENT:
        CycleStep := E_AutoCycleStep.AX12_LOADED_ASCENT;
        CycleStateStr := 'AX12 - Remontee en charge';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040C;
        OperatorAction := 'AX12 - Maintenir la montee en charge jusqu a la limite haute.';

        // Benne bien fermee -> palier 4 ; benne mal fermee (a peu pres) -> palier 1.
        // Pas de ralentissement 1 m avant la position top (montee franche).
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := TRUE; WinchM1Cmd.ReqDescend := FALSE;
        WinchM1Cmd.StepTgt  := SEL(Benne_IsClosed, CST_StepSlow, CST_StepLoaded);
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := TRUE; WinchM2Cmd.ReqDescend := FALSE;
        WinchM2Cmd.StepTgt  := SEL(Benne_IsClosed, CST_StepSlow, CST_StepLoaded);

        IF JoystickDeflected AND M1_CablePosM >= CableLimitM1AscentM THEN
            WinchM1Cmd.RunRequest := FALSE;
            WinchM2Cmd.RunRequest := FALSE;
            State := E_AutoCycleStep.AX13_DRAIN_PAUSE;
        END_IF;

    (* ===================== DECHARGE (AX13..AX18) ===================== *)

    E_AutoCycleStep.AX13_DRAIN_PAUSE:
        CycleStep := E_AutoCycleStep.AX13_DRAIN_PAUSE;
        CycleStateStr := 'AX13 - Egouttage du godet en cours';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.NONE;
        ExpectedDirection := 0;
        WaitingForOperator := FALSE;
        WaitingForProcess := TRUE;
        OperatorActionId := 16#0409;
        OperatorAction := 'AX13 - Egouttage : attendre la tempo ou appuyer sur "passer egouttage".';
        WinchM1Cmd.RunRequest := FALSE;
        WinchM2Cmd.RunRequest := FALSE;

        // Tempo d'egouttage armee/remise a zero en §1 (gate sur State = AX13, PT = DrainTimeEff).
        // Duree reglable IHM (CfgDrainTime) + bypass immediat (SkipDrainEdge).
        IF JoystickDeflected AND (DrainingTimer.Q OR SkipDrainEdge.Q) THEN
            State := E_AutoCycleStep.AX14_TRANSLATE_DUMP;
        END_IF;

    E_AutoCycleStep.AX14_TRANSLATE_DUMP:
        CycleStep := E_AutoCycleStep.AX14_TRANSLATE_DUMP;
        CycleStateStr := 'AX14 - Deplacement vers tremie (grille/crible libres)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_X;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040A;
        OperatorAction := 'AX14 - Maintenir la translation vers la tremie de dechargement.';

        TranslationCmd.PositionTgt := 1; // Trémie
        TranslationCmd.ReqStart := CycleMotionPermit;

        IF JoystickDeflected AND Translation_At_Tremie THEN
            TranslationCmd.ReqStart := FALSE;
            State := E_AutoCycleStep.AX15A_DUMP_ARRIVE;
        END_IF;

    E_AutoCycleStep.AX15A_DUMP_ARRIVE:
        CycleStep := E_AutoCycleStep.AX15A_DUMP_ARRIVE;
        CycleStateStr := 'AX15a - Arrivee tremie : treuils arretes, attente ouverture';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040B;
        OperatorAction := 'AX15a - A la tremie : deflechir vers le bas pour ouvrir la benne et vider.';

        // Config treuil UNIQUE : arret des deux treuils (aucune descente couplee ici).
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;

        // Geste operateur (manche defleci) -> phase d'ouverture benne.
        IF JoystickDeflected THEN
            State := E_AutoCycleStep.AX15B_DUMP_OPEN;
        END_IF;

    E_AutoCycleStep.AX15B_DUMP_OPEN:
        CycleStep := E_AutoCycleStep.AX15B_DUMP_OPEN;
        CycleStateStr := 'AX15b - Vidage : ouverture benne pour vider le contenu, treuils arretes';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040B;
        OperatorAction := 'AX15b - Maintenir : ouverture complete de la benne, vidage a la tremie.';

        // Config treuil UNIQUE : etape benne seule, les deux treuils neutralises
        // (plus de descente couplee M1+M2 simultanee a l'ouverture benne -> plus
        // d'ecart M1/M2 volontaire ni de faux SafeStop concordance contacteurs).
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;

        BucketCmd.ReqOpen := CycleMotionPermit;

        // Option operateur (bit IHM) : descendre la benne dans la gueule de tremie
        // pour aider la vidange -> repositionnement couple M1+M2 (AX15C). Prioritaire
        // sur la fin de vidage.
        IF RepositionRequest THEN
            State := E_AutoCycleStep.AX15C_DUMP_REPOSITION;
        ELSIF JoystickDeflected AND Benne_Done AND Benne_IsOpen THEN
            BucketCmd.ReqOpen := FALSE;
            State := E_AutoCycleStep.AX18_DONE_SYNC;
        END_IF;

    E_AutoCycleStep.AX15C_DUMP_REPOSITION:
        CycleStep := E_AutoCycleStep.AX15C_DUMP_REPOSITION;
        CycleStateStr := 'AX15c - Repositionnement couple M1+M2 (aide vidange tremie)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040C;
        OperatorAction := 'AX15c - Descente couplee M1+M2 ; relacher l option pour reprendre le vidage.';

        // Descente couplee M1+M2, palier lent, sous homme-mort. Commandes SYMETRIQUES
        // (meme sens, meme palier) -> FB_SyncDeviation actif, pas d'ecart volontaire.
        WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := TRUE;
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.StepTgt := CST_StepSlow;
        WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := TRUE;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.StepTgt := CST_StepSlow;

        // La benne reste ouverte pendant le repositionnement (on finit l'ouverture si besoin).
        BucketCmd.ReqOpen := CycleMotionPermit AND NOT Benne_IsOpen;

        // Retour a AX15B des que l'operateur relache l'option de repositionnement.
        IF NOT RepositionRequest THEN
            WinchM1Cmd.RunRequest := FALSE;
            WinchM2Cmd.RunRequest := FALSE;
            State := E_AutoCycleStep.AX15B_DUMP_OPEN;
        END_IF;

    E_AutoCycleStep.AX18_DONE_SYNC:
        CycleStep := E_AutoCycleStep.AX18_DONE_SYNC;
        CycleStateStr := 'AX18 - Passe terminee : aller en P1 pour recommencer';
        WinchM1Cmd.RunRequest := FALSE;
        WinchM2Cmd.RunRequest := FALSE;
        TranslationCmd.ReqStart := FALSE;
        Lifecycle.Done := TRUE;
        Lifecycle.Busy := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_X;
        ExpectedDirection := 1;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#040D;
        OperatorAction := 'AX18 - Cycle termine. Aller en P1 (joystick vers la droite) pour recommencer.';

        // Compteur de prélèvements (RETAIN) + durée du cycle — F2: cadré par front (1 seul par cycle)
        IF NOT SampleCountDone THEN
            SampleCount := SampleCount + 1;
            LastCycleDuration := CurrentCycleElapsed;   // fige la durée du cycle qui vient de s'achever
            SampleCountDone := TRUE;
        END_IF;

        // Rebouclage DIRECT sur AX2_TRANSLATE_P1 (GEL Q14) : la machine est deja
        // referencee, la passe suivante enchaine sur la translation P1 (pas de retour AX0).
        // Relance sur StartCycle OU FRONT joystick (geste franc) - pas sur simple maintien,
        // pour que AX18 (Lifecycle.Done + msg) soit reellement observable / tracable.
        IF StartEdge.Q OR JoyDeflectedEdge.Q THEN
            SampleCountDone := FALSE;
            Lifecycle.Done := FALSE;
            State := E_AutoCycleStep.AX2_TRANSLATE_P1;
        END_IF;

    E_AutoCycleStep.AX_STAB:
        CycleStep := E_AutoCycleStep.AX_STAB;
        CycleStateStr := 'AX_STAB - Cycle en attente / stabilisation sur anomalie';
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE;
        TranslationCmd.ReqStart := FALSE;
        BucketCmd.ReqOpen := FALSE;
        BucketCmd.ReqClose := FALSE;
        BucketCmd.ReqKoboldMeasureEnable := FALSE;   // Coupure contacteur Kobold au repli defaut (0 ordre residuel)
        Lifecycle.Busy := FALSE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.BUTTON;
        ExpectedDirection := 0;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#0480;
        OperatorAction := 'AX_STAB - Cycle stabilise sur anomalie : acquitter le defaut pour reinitialiser.';

END_CASE;
END_IF;
{endregion}

{region "§4 Repli homme mort & Syntheses"}
// 🛑 Relâchement du manche (retour au centre) OU de l'homme-mort : neutralisation
// des demandes actives. Gate continu : aucune commande d'actionneur ne survit à la
// perte du permis opérateur (manche défléchi ET homme-mort armé).
IF Lifecycle.Busy AND NOT CycleMotionPermit THEN
    WinchM1Cmd.RunRequest := FALSE;
    WinchM2Cmd.RunRequest := FALSE;
    TranslationCmd.ReqStart := FALSE;
    BucketCmd.ReqOpen := FALSE;
    BucketCmd.ReqClose := FALSE;
    BucketCmd.ReqKoboldMeasureEnable := FALSE;
END_IF;

RequestActive := WinchM1Cmd.RunRequest OR WinchM2Cmd.RunRequest OR TranslationCmd.ReqStart OR BucketCmd.ReqOpen OR BucketCmd.ReqClose OR BucketCmd.ReqKoboldMeasureEnable; // Somme logique complete des demandes (contacteur Kobold inclus)
{endregion}

{region "§1 Fronts, calculs et causes"}
ResetEdge(CLK := Reset);
KoboldRiseEdge(CLK := Inputs.KoboldImmersed);
KoboldFallEdge(CLK := Inputs.KoboldImmersed);

// Les valeurs par defaut du DUT couvrent l'appel sans configuration explicite.
// Le repli runtime protege aussi un appel avec une structure entierement nulle.
EffectiveDiveSpeedMin_Mps := Inputs.Config.DiveSpeedMin_Mps;
IF EffectiveDiveSpeedMin_Mps <= 0.0 THEN EffectiveDiveSpeedMin_Mps := 0.15; END_IF;
EffectiveTimeoutMargin := Inputs.Config.TimeoutMarginFactor;
IF EffectiveTimeoutMargin <= 0.0 THEN EffectiveTimeoutMargin := 1.5; END_IF;
EffectiveTimeoutMinCourse_M := Inputs.Config.TimeoutMinCourse_M;
IF EffectiveTimeoutMinCourse_M <= 0.0 THEN EffectiveTimeoutMinCourse_M := 1.0; END_IF;
EffectiveTimeoutMaxCourse_M := Inputs.Config.TimeoutMaxCourse_M;
IF EffectiveTimeoutMaxCourse_M < EffectiveTimeoutMinCourse_M THEN EffectiveTimeoutMaxCourse_M := 200.0; END_IF;
EffectiveSecToMs := Inputs.Config.SecToMs;
IF EffectiveSecToMs <= 0.0 THEN EffectiveSecToMs := 1000.0; END_IF;

ErrorCausePresent := (Inputs.CycleTime <= T#0ms)
                 OR (NOT Inputs.BypassPreconditions AND (
                       (Inputs.DiveStartMin_M < Inputs.ImmersionUpper_M)
                    OR (Inputs.ImmersionUpper_M <= Inputs.ImmersionLower_M)
                    OR (Inputs.ImmersionLower_M <= Inputs.LimitLegalDepthMin_M)
                    OR (Inputs.CableLimitAscent_M <= Inputs.ImmersionLower_M)));

ImmersionCourse_M := LIMIT(EffectiveTimeoutMinCourse_M,
                           Inputs.CableLimitAscent_M - Inputs.ImmersionLower_M,
                           EffectiveTimeoutMaxCourse_M);
BottomCourse_M := LIMIT(EffectiveTimeoutMinCourse_M,
                        Inputs.ImmersionLower_M - Inputs.LimitLegalDepthMin_M,
                        EffectiveTimeoutMaxCourse_M);
CalculatedImmersionTimeout := UDINT_TO_TIME(REAL_TO_UDINT(
    ImmersionCourse_M / EffectiveDiveSpeedMin_Mps * EffectiveTimeoutMargin * EffectiveSecToMs));
CalculatedBottomTimeout := UDINT_TO_TIME(REAL_TO_UDINT(
    BottomCourse_M / EffectiveDiveSpeedMin_Mps * EffectiveTimeoutMargin * EffectiveSecToMs));

IF (Outputs.StepState = E_DiveSearchState.SEARCHING_IMMERSION)
   AND Inputs.MotionRequestActive AND (Inputs.MotionDirection = -1) THEN
    ImmersionTimerAcc := ImmersionTimerAcc + Inputs.CycleTime;
    IF ImmersionTimerAcc >= CalculatedImmersionTimeout THEN TimeoutImmersionFault := TRUE; END_IF;
END_IF;

IF (Outputs.StepState = E_DiveSearchState.SEARCHING_BOTTOM)
   AND Inputs.MotionRequestActive AND (Inputs.MotionDirection = -1) THEN
    BottomTimerAcc := BottomTimerAcc + Inputs.CycleTime;
    IF BottomTimerAcc >= CalculatedBottomTimeout THEN TimeoutBottomFault := TRUE; END_IF;
END_IF;

IF ResetEdge.Q AND NOT ErrorCausePresent AND NOT Inputs.KoboldImmersed
   AND NOT Inputs.MotionRequestActive AND NOT (Inputs.CurrentSpeedStep > 4) THEN
    SeqErrorFault := FALSE;
    Palier5ForbiddenFault := FALSE;
    TimeoutImmersionFault := FALSE;
    TimeoutBottomFault := FALSE;
    ImmersionTimerAcc := T#0ms;
    BottomTimerAcc := T#0ms;
    ImmersionConfirmed := FALSE;
    Outputs.BottomTouchConfirmed := FALSE;
    Outputs.StepAtFault := E_DiveSearchState.WAIT_PRECONDITIONS;
    StepAtFaultCaptured := FALSE;
    Outputs.StepState := E_DiveSearchState.WAIT_PRECONDITIONS;
END_IF;

instCauses[0].Active := SeqErrorFault;
instCauses[0].Latching := TRUE;
instCauses[0].Texte := 'Incoherence sequence immersion Kobold';
instCauses[1].Active := ErrorCausePresent;
instCauses[1].Latching := TRUE;
instCauses[1].Texte := 'Parametrage invalide des seuils de plongee';
instCauses[2].Active := Palier5ForbiddenFault;
instCauses[2].Latching := TRUE;
instCauses[2].Texte := 'Palier 5 interdit pendant la mesure Kobold';
instCauses[3].Active := TimeoutImmersionFault;
instCauses[3].Latching := TRUE;
instCauses[3].Texte := 'Timeout recherche immersion Kobold';
instCauses[4].Active := TimeoutBottomFault;
instCauses[4].Latching := TRUE;
instCauses[4].Texte := 'Timeout recherche fond Kobold';

instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

ErrorEdge(CLK := Fault.Error);
IF ErrorEdge.Q AND NOT StepAtFaultCaptured THEN
    Outputs.StepAtFault := PrevState;
    StepAtFaultCaptured := TRUE;
ELSIF ResetEdge.Q AND NOT ErrorCausePresent AND NOT Inputs.KoboldImmersed
      AND NOT Inputs.MotionRequestActive AND NOT (Inputs.CurrentSpeedStep > 4) THEN
    Outputs.StepAtFault := E_DiveSearchState.WAIT_PRECONDITIONS;
END_IF;
{endregion}

{region "§2 Neutralisation et machine d'etat"}
IF NOT Enable OR NOT Inputs.PowerContactorEngaged THEN
    Ready := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    Outputs.DescendPermit := FALSE;
    Outputs.KoboldContactorCmd := FALSE;
    Outputs.BottomTouchConfirmed := FALSE;
    Outputs.StepState := E_DiveSearchState.WAIT_PRECONDITIONS;
    Outputs.OperatorActionId := 0;
    Outputs.OperatorAction := '';
    ImmersionConfirmed := FALSE;
    ImmersionTimerAcc := T#0ms;
    BottomTimerAcc := T#0ms;
    Outputs.MinStepDown := 0;
    PrevState := E_DiveSearchState.WAIT_PRECONDITIONS;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
Outputs.DescendPermit := FALSE;
Outputs.KoboldContactorCmd := FALSE;
Lifecycle.Busy := FALSE;
Lifecycle.Done := FALSE;
Outputs.OperatorActionId := 0;
Outputs.OperatorAction := '';

DescentActive := Inputs.MotionRequestActive AND (Inputs.MotionDirection = -1)
              AND ((Inputs.Mode = E_Mode.MAINT_N1) OR (Inputs.Mode = E_Mode.MAINT_N2))
              AND NOT (Inputs.CurrentSpeedStep > 4)
              AND NOT SeqErrorFault;

IF Fault.Error OR Fault.Latched THEN
    Outputs.StepState := E_DiveSearchState.ERROR_HOLD;
    Outputs.KoboldContactorCmd := FALSE;
    Outputs.OperatorActionId := 16#0180;
    Outputs.OperatorAction := 'Verifier les conditions puis rearmer avant une nouvelle plongee.';
ELSE
    CASE Outputs.StepState OF
        E_DiveSearchState.WAIT_PRECONDITIONS:
            IF NOT Inputs.BypassPreconditions
               AND (NOT Inputs.BucketIsOpen OR NOT Inputs.PositionsValid OR Inputs.KoboldImmersed
                    OR (Inputs.M1Position_M < Inputs.DiveStartMin_M)
                    OR (Inputs.M2Position_M < Inputs.DiveStartMin_M)) THEN
                Outputs.OperatorActionId := 16#0100;
                Outputs.OperatorAction := 'Verifier benne ouverte, positions et Kobold au repos.';
            ELSE
                Outputs.StepState := E_DiveSearchState.READY_TO_DESCEND;
            END_IF;

        E_DiveSearchState.READY_TO_DESCEND:
            Ready := TRUE;
            Outputs.OperatorActionId := 16#0101;
            Outputs.OperatorAction := 'Demander une descente pour rechercher le fond.';
            IF Inputs.MotionRequestActive AND (Inputs.MotionDirection = -1) THEN
                ImmersionTimerAcc := T#0ms;
                Outputs.StepState := E_DiveSearchState.SEARCHING_IMMERSION;
            END_IF;

        E_DiveSearchState.SEARCHING_IMMERSION:
            Lifecycle.Busy := TRUE;
            Outputs.DescendPermit := DescentActive;
            Outputs.KoboldContactorCmd := DescentActive;
            Outputs.OperatorActionId := 16#0102;
            Outputs.OperatorAction := 'Maintenir la descente : recherche immersion Kobold.';
            IF Inputs.CurrentSpeedStep > 4 THEN
                IF NOT StepAtFaultCaptured THEN
                    Outputs.StepAtFault := Outputs.StepState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                Palier5ForbiddenFault := TRUE;
            END_IF;
            IF KoboldRiseEdge.Q THEN
                IF (Inputs.M1Position_M <= Inputs.ImmersionUpper_M)
                   AND (Inputs.M1Position_M >= Inputs.ImmersionLower_M)
                   AND (Inputs.M2Position_M <= Inputs.ImmersionUpper_M)
                   AND (Inputs.M2Position_M >= Inputs.ImmersionLower_M) THEN
                    ImmersionConfirmed := TRUE;
                    BottomTimerAcc := T#0ms;
                    Outputs.StepState := E_DiveSearchState.SEARCHING_BOTTOM;
                ELSE
                    IF NOT StepAtFaultCaptured THEN
                        Outputs.StepAtFault := Outputs.StepState;
                        StepAtFaultCaptured := TRUE;
                    END_IF;
                    SeqErrorFault := TRUE;
                END_IF;
            ELSIF (Inputs.M1Position_M < Inputs.ImmersionLower_M)
               OR (Inputs.M2Position_M < Inputs.ImmersionLower_M) THEN
                IF NOT StepAtFaultCaptured THEN
                    Outputs.StepAtFault := Outputs.StepState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                SeqErrorFault := TRUE;
            END_IF;

        E_DiveSearchState.SEARCHING_BOTTOM:
            Lifecycle.Busy := TRUE;
            Outputs.DescendPermit := DescentActive;
            Outputs.KoboldContactorCmd := DescentActive;
            Outputs.OperatorActionId := 16#0103;
            Outputs.OperatorAction := 'Maintenir la descente : immersion validee, recherche du fond.';
            IF Inputs.CurrentSpeedStep > 4 THEN
                IF NOT StepAtFaultCaptured THEN
                    Outputs.StepAtFault := Outputs.StepState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                Palier5ForbiddenFault := TRUE;
            END_IF;
            IF KoboldFallEdge.Q AND ImmersionConfirmed THEN
                Outputs.BottomTouchConfirmed := TRUE;
                ImmersionConfirmed := FALSE;
                Outputs.KoboldContactorCmd := FALSE;
                Outputs.StepState := E_DiveSearchState.BOTTOM_CONFIRMED;
            END_IF;

        E_DiveSearchState.BOTTOM_CONFIRMED:
            Lifecycle.Done := TRUE;
            Outputs.KoboldContactorCmd := FALSE;
            Outputs.OperatorActionId := 16#0104;
            Outputs.OperatorAction := 'Fond detecte : demander la fermeture ou extraction.';

        E_DiveSearchState.ERROR_HOLD:
            Outputs.KoboldContactorCmd := FALSE;
    END_CASE;
END_IF;

IF DescentActive AND ((Outputs.StepState = E_DiveSearchState.SEARCHING_IMMERSION)
                   OR (Outputs.StepState = E_DiveSearchState.SEARCHING_BOTTOM)) THEN
    Outputs.MinStepDown := LIMIT(0, Inputs.CfgDiveFloorStep, 5);
ELSE
    Outputs.MinStepDown := 0;
END_IF;

PrevState := Outputs.StepState;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);
// Parametrage invalide : distance nulle, backstop nul, base de temps nulle, ou backstop
// qui fauterait AVANT le watchdog benne (masquerait BucketError - ordre des watchdogs).
ErrorCausePresent := (ControlAscentDistance_M <= 0.0)
                  OR (CfgBucketCloseTimeout <= T#0ms)
                  OR (CycleTime <= T#0ms)
                  OR (CfgBucketCloseTimeout <= BucketMoveTimeout)
                  OR (CfgBucketCloseTimeout > CST_BackstopMax);  // borne haute : evite l'overflow de BucketCloseTimerAcc (F3)

// ⏱️ Plafond anti-blocage decollage calcule au runtime : course de controle bornee [plancher..plafond]
// avant conversion REAL->UDINT->TIME (anti-overflow sur valeur IHM aberrante, CQS §6).
CalculatedControlAscentTimeout := UDINT_TO_TIME(REAL_TO_UDINT(
    LIMIT(CST_TimeoutMinDistance_M, ControlAscentDistance_M, CST_TimeoutMaxDistance_M)
    / CST_MinSpeed_Mps * CST_ControlAscentMargin * CST_SecToMs));

// ⏱️ Integrateurs de temps de montee effective (anti-pompage homme-mort)
IF (ExtractionState = E_ExtractionAssistState.CLOSING_BUCKET) AND MotionRequestActive AND (MotionDirection = 1) THEN
    BucketCloseTimerAcc := BucketCloseTimerAcc + CycleTime;
    IF BucketCloseTimerAcc >= CfgBucketCloseTimeout THEN
        TimeoutBucketCloseFault := TRUE;
    END_IF;
END_IF;

IF (ExtractionState = E_ExtractionAssistState.CONTROL_ASCENT) AND MotionRequestActive AND (MotionDirection = 1) THEN
    ControlAscentTimerAcc := ControlAscentTimerAcc + CycleTime;
    IF ControlAscentTimerAcc >= CalculatedControlAscentTimeout THEN
        TimeoutControlAscentFault := TRUE;
    END_IF;
END_IF;

// Etat physique des causes treuil/benne : conditionne l'acquittement des latches a cause persistante (F2).
CausesPhysiquesEffacees := NOT BucketError AND NOT WinchSyncError
                        AND PositionsValid AND M1MeasuredSpeedValid AND M2MeasuredSpeedValid;
IF ResetEdge.Q AND NOT ErrorCausePresent AND NOT MotionRequestActive THEN
    // Latches sans cause physique persistante (timeouts, backstop) : acquittables sur simple front Reset.
    TimeoutBucketCloseFault   := FALSE;
    TimeoutControlAscentFault := FALSE;
    BucketCloseTimerAcc       := T#0ms;
    ControlAscentTimerAcc     := T#0ms;
    StepAtFaultCaptured       := FALSE;
    ExtractionState := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
    // Latches de cause physique : acquittables SEULEMENT si l'entree de defaut est revenue saine (F2).
    IF CausesPhysiquesEffacees THEN
        BucketErrorFault      := FALSE;
        SyncOrSpeedErrorFault := FALSE;
    END_IF;
END_IF;

instCauses[1].Active   := BucketErrorFault;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Defaut sous-systeme benne pendant fermeture';

instCauses[2].Active   := SyncOrSpeedErrorFault;
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Defaut synchro ou capteurs treuils pendant remontee';

instCauses[3].Active   := ErrorCausePresent;
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Parametrage distance de controle ou backstop invalide';

instCauses[4].Active   := TimeoutBucketCloseFault;
instCauses[4].Latching := TRUE;
instCauses[4].Texte    := 'Depassement backstop fermeture benne';

instCauses[5].Active   := TimeoutControlAscentFault;
instCauses[5].Latching := TRUE;
instCauses[5].Texte    := 'Depassement tempo decollage controle';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// 📸 Capture ordonnee de StepAtFault (D2). Les defauts leves dans le CASE se figent au site du
// latch (voir §3) ; ce bloc ne couvre que les defauts detectes en §1 (backstop, timeout, parametrage),
// ou ExtractionState/PrevState sont encore l'etape reelle. StepAtFaultCaptured evite l'ecrasement.
ErrorEdge(CLK := Fault.Error);
IF ErrorEdge.Q AND NOT StepAtFaultCaptured THEN
    StepAtFault := PrevState;
    StepAtFaultCaptured := TRUE;
ELSIF ResetEdge.Q AND NOT ErrorCausePresent AND NOT MotionRequestActive THEN
    StepAtFault := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
END_IF;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    BucketCloseRequest := FALSE;
    AscentPermit := FALSE;
    ExtractionControlActive := FALSE;
    BottomConfirmationConsumed := FALSE;
    ExtractionState := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
    // StepAtFault / StepAtFaultCaptured NON reinitialises ici : l'etape figee au defaut reste
    // lisible pour l'IHM/diagnostic apres un cycle Enable OFF->ON ; seul un front Reset l'efface.
    PrevState := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
    BucketCloseTimerAcc := T#0ms;
    ControlAscentTimerAcc := T#0ms;
    OperatorActionId := 0;
    OperatorAction := '';
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Machine etat fermeture remontee"}
BucketCloseRequest := FALSE;
AscentPermit := FALSE;
ExtractionControlActive := FALSE;
BottomConfirmationConsumed := FALSE;
Lifecycle.Busy := FALSE;
Lifecycle.Done := FALSE;

// Ascending assistee reellement demandee : sens ascending + mode maintenance (H5, double garde vs Enable PRG_03).
AssistPermit := MotionRequestActive AND (MotionDirection = 1)
            AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2);
// Entrees [SAFE] saines : coupure meme-scan des permis si defaut treuil/synchro (H2), avant meme le latch.
AscentControlSafe := NOT WinchSyncError AND PositionsValid AND M1MeasuredSpeedValid AND M2MeasuredSpeedValid;
AscentNominalSafe := NOT WinchSyncError AND PositionsValid;

// Garde-fou non-redemarrage auto : un defaut latche non acquitte verrouille la machine
// d'etat en ERROR_HOLD, meme si la vue live Fault.Error retombe (cause disparue).
IF Fault.Error OR Fault.Latched THEN
    ExtractionState := E_ExtractionAssistState.ERROR_HOLD;
    OperatorActionId := 16#0280;
    OperatorAction := 'Vérifier la benne et les treuils puis réarmer avant de reprendre.';
ELSE
    CASE ExtractionState OF
        E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION:
            IF BottomPositionConfirmed THEN
                ExtractionState := E_ExtractionAssistState.READY_TO_CLOSE;
            ELSE
                OperatorActionId := 16#0200;
                OperatorAction := 'Confirmer que la benne est posée au fond avant extraction.';
            END_IF;

        E_ExtractionAssistState.READY_TO_CLOSE:
            Ready := TRUE;
            OperatorActionId := 16#0201;
            OperatorAction := 'Demander la montée pour fermer la benne.';
            IF MotionRequestActive AND (MotionDirection = 1) THEN
                BottomConfirmationConsumed := TRUE;
                BucketCloseTimerAcc := T#0ms;   // ⏱️ RAZ a l'entree exacte de CLOSING_BUCKET
                ExtractionState := E_ExtractionAssistState.CLOSING_BUCKET;
            END_IF;

        E_ExtractionAssistState.CLOSING_BUCKET:
            Lifecycle.Busy := TRUE;
            BucketCloseRequest := AssistPermit AND NOT BucketError; // coupure meme-scan sur defaut benne (H2)
            // Autorisation de montee pendant la fermeture : la benne se ferme en montant.
            // Consommee par l'arbitrage (PRG_04) comme permis de montee assistee (H2).
            AscentPermit := AssistPermit AND AscentControlSafe;
            OperatorActionId := 16#0202;
            OperatorAction := 'Maintenir la montée : fermeture de la benne en cours.';
            IF BucketError THEN
                IF NOT StepAtFaultCaptured THEN
                    StepAtFault := ExtractionState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                BucketErrorFault := TRUE;
            ELSIF BucketIsClosed AND NOT BucketBusy THEN
                ControlStartM1Position_M := M1Position_M;
                ControlStartM2Position_M := M2Position_M;
                ControlAscentTimerAcc := T#0ms;   // ⏱️ RAZ a l'entree exacte de CONTROL_ASCENT
                ExtractionState := E_ExtractionAssistState.CONTROL_ASCENT;
            END_IF;

        E_ExtractionAssistState.CONTROL_ASCENT:
            Lifecycle.Busy := TRUE;
            AscentPermit := AssistPermit AND AscentControlSafe; // coupure meme-scan sur defaut synchro/capteurs (H2)
            ExtractionControlActive := AscentPermit;            // plafond palier 1 suit le permis de montee
            OperatorActionId := 16#0203;
            OperatorAction := 'Maintenir la montée : contrôle charge au palier minimal.';
            IF NOT AscentControlSafe THEN
                IF NOT StepAtFaultCaptured THEN
                    StepAtFault := ExtractionState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                SyncOrSpeedErrorFault := TRUE;
            ELSIF (M1Position_M >= (ControlStartM1Position_M + ControlAscentDistance_M))
               AND (M2Position_M >= (ControlStartM2Position_M + ControlAscentDistance_M)) THEN
                ExtractionState := E_ExtractionAssistState.NOMINAL_ASCENT;
            END_IF;

        E_ExtractionAssistState.NOMINAL_ASCENT:
            Lifecycle.Busy := TRUE;
            AscentPermit := AssistPermit AND AscentNominalSafe; // coupure meme-scan sur defaut synchro/position (H2)
            OperatorActionId := 16#0204;
            OperatorAction := 'Maintenir la montée : extraction en cours.';
            IF NOT AscentNominalSafe THEN
                IF NOT StepAtFaultCaptured THEN
                    StepAtFault := ExtractionState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                SyncOrSpeedErrorFault := TRUE;
            END_IF;

        E_ExtractionAssistState.ERROR_HOLD:
            ;
    END_CASE;
END_IF;

// 💾 Memorisation de la phase precedente en toute fin de scan (capture StepAtFault fiable)
PrevState := ExtractionState;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESTAURATION BOOT DES DRAPEAUX PERSISTANTS
// Non-RETAIN -> réinitialisé à chaque warm/cold reset ; relu depuis GVL_PERSISTENT (miroir
// réécrit chaque scan par PRG_03). Aucune perte du re-homing obligatoire sur coupure.
IF NOT FirstScanDone THEN
    FirstScanDone         := TRUE;
    MaintHomingRequiredM1 := BootHomingRequiredM1;
    MaintHomingRequiredM2 := BootHomingRequiredM2;
    PrevArbitratedMode    := E_Mode.DISABLE;
END_IF;

// 🔑 1ter. RE-HOMING OBLIGATOIRE — ARMEMENT IMMÉDIAT (AF-05 §4bis)
// Armé AVANT l'arbitrage de mode (§3) et non à la sortie du mode maintenance :
//   1. pas de fenêtre d'un scan où le re-homing serait perdu malgré un override effectif ;
//   2. pas de perte de l'obligation sur coupure / download pendant la maintenance
//      (la valeur est écrite dans le miroir PERSISTENT dès le scan courant, pas à la sortie).
// Le re-homing ne bloque PAS la sélection SEMI_AUTO : il est publié à l'IHM
// (Auth.HomingRequiredM1/M2) et le cycle ne progresse pas tant qu'il n'est pas levé.
IF M1PositionLimitOverridden THEN
    MaintHomingRequiredM1 := TRUE;
END_IF;
IF M2PositionLimitOverridden THEN
    MaintHomingRequiredM2 := TRUE;
END_IF;

// Levée : UNIQUEMENT sur cycle de homing complet réussi (Done + Homed + non suspect).
IF MaintHomingRequiredM1 AND M1HomingDone AND M1Homed AND NOT M1HomingSuspect THEN
    MaintHomingRequiredM1 := FALSE;
END_IF;
IF MaintHomingRequiredM2 AND M2HomingDone AND M2Homed AND NOT M2HomingSuspect THEN
    MaintHomingRequiredM2 := FALSE;
END_IF;

// Diagnostic « cycle non prêt » — le mode SEMI_AUTO reste sélectionnable mais le
// cycle ne tournera pas tant que ces conditions ne sont pas saines. Info NON-bloquante :
// la sélection n'est pas refusée, le mouvement est coupé en aval (FB_CycleSemiAuto/FB_Safety_Winch).
// Une cause = un fait (AF03 §4) : défaut codeur, re-homing et référencement sont distincts.
SemiAutoCycleNotReadyFault         := (SelMode = E_Mode.SEMI_AUTO) AND EncoderFaultPresent;
SemiAutoCycleNotReadyHoming        := (SelMode = E_Mode.SEMI_AUTO) AND (MaintHomingRequiredM1 OR MaintHomingRequiredM2);
SemiAutoCycleNotReadyMachineHoming := (SelMode = E_Mode.SEMI_AUTO) AND NOT MachineHomed;

instCauses[0].Active   := SemiAutoCycleNotReadyFault;
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Mode Semi-Auto selectionne mais cycle non pret : defaut codeur present';

instCauses[2].Active   := SemiAutoCycleNotReadyHoming;
instCauses[2].Latching := FALSE;
instCauses[2].Texte    := 'Semi-Auto selectionne : re-homing obligatoire';

instCauses[3].Active   := SemiAutoCycleNotReadyMachineHoming;
instCauses[3].Latching := FALSE;
instCauses[3].Texte    := 'Semi-Auto selectionne : referencement incomplet';

// Cause 1 — changement de mode refusé : treuils non à l'arrêt mécanique confirmé.
// Non latchée (live) : l'information disparaît dès que la condition redevient vraie, sans
// acquittement — c'est une consigne d'action IHM (« arrêter les treuils »), pas un défaut machine.
// 📌 Lag 1 scan assumé : la cause est évaluée avant l'arbitrage §3 du cycle courant.
instCauses[1].Active   := Auth.ModeChangePendingBlocked;
instCauses[1].Latching := FALSE;
instCauses[1].Texte    := 'Changement de mode refuse : arreter les treuils avant de changer de mode';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE — neutralisation si désactivé (l'arbitrage de mode reste actif même AU non armé :
//    homing, réarmement défaut. Aucune autorisation de mouvement n'est accordée sans la chaîne
//    AU physique : chaque FB de mouvement garde son propre gate PowerContactorEngaged.)
IF NOT Enable THEN
    Auth.Mode := E_Mode.DISABLE;
    Auth.SyncEnable := TRUE;
    Auth.InhibitM1 := FALSE;
    Auth.InhibitM2 := FALSE;
    Auth.HomingApproachEnable := FALSE;
    Auth.JoystickWinchSelectArbitrated := 0;  // Couplé nominal par défaut
    Auth.CoupledBucketPhaseLocked := FALSE;
    Auth.WinchSelTransitionHold := FALSE;
    BucketSeqSatisfied := FALSE;
    Auth.MaintenanceM3TargetEnable := FALSE;
    // Faits persistants : PUBLIÉS même neutralisé (l'IHM doit continuer à voir
    // qu'un re-homing est requis tant que la machine n'est pas réarmée). Aucune autorisation
    // n'est accordée ici : Auth.Mode := DISABLE verrouille tout le reste.
    Auth.ModeChangePendingBlocked := FALSE;
    Auth.ModeChangeBlockReason := '';
    Auth.HomingRequiredM1 := MaintHomingRequiredM1;
    Auth.HomingRequiredM2 := MaintHomingRequiredM2;
    PrevArbitratedMode := Auth.Mode;
    Ready := FALSE;
    PrevInhibitM1 := FALSE;
    PrevInhibitM2 := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Arbitrage du mode"}
// ⚙️ 3. ARBITRAGE DU MODE

// 3.1 ARRÊT MÉCANIQUE CONFIRMÉ DES DEUX TREUILS (condition de bascule, AF-05 §4bis)
// Même composite que l'armement Méca B : contacteurs retombés + frein serré, redondé par
// la mesure absolue de vitesse. Vaut pour les DEUX treuils (M1 ET M2).
ModeChangeAllowed := M1ContactorsReleased AND NOT M1BrakeIsOpen
                     AND (ABS(M1SpeedAbsMps) < MovementSpeedThresholdMps)
                     AND M2ContactorsReleased AND NOT M2BrakeIsOpen
                     AND (ABS(M2SpeedAbsMps) < MovementSpeedThresholdMps);

// Détail des 6 sous-conditions (diagnostic IHM) — TRUE = condition satisfaite.
// Permet à l'opérateur de voir EXACTEMENT ce qui bloque la bascule de mode.
Auth.M1ContactorsReleased := M1ContactorsReleased;
Auth.M1BrakeApplied       := NOT M1BrakeIsOpen;
Auth.M1SpeedLow           := ABS(M1SpeedAbsMps) < MovementSpeedThresholdMps;
Auth.M2ContactorsReleased := M2ContactorsReleased;
Auth.M2BrakeApplied       := NOT M2BrakeIsOpen;
Auth.M2SpeedLow           := ABS(M2SpeedAbsMps) < MovementSpeedThresholdMps;

// 3.2 ARBITRAGE — le mode suit la sélection IHM (découplé de l'AU/défaut)
// La sélection de mode n'est JAMAIS bloquée par l'AU, l'arrêt d'urgence ou un défaut :
// le mode est un état de sélection, le mouvement est coupé en aval (FB_CycleSemiAuto, FB_Safety_Winch,
// FB_Winch) par PowerContactorEngaged et les interlocks. Seule la bascule N1/N2/SEMI_AUTO
// reste soumise à l'arrêt mécanique confirmé des treuils (ModeChangeAllowed).
// 3.2bis (AF-05 §4bis - referencement benne guide) : SEMI_AUTO est un mode "homed-only".
// Une selection SEMI_AUTO sans datum machine valide (MachineHomed) est REFUSEE et le mode
// est force vers MAINT_N1 (expulsion). Vaut aussi si MachineHomed retombe alors qu'on EST
// en SEMI_AUTO (perte de datum -> bascule MAINT_N1). Le SafeStop des treuils sur perte de
// datum en mouvement est assure en aval (PRG_04 via MachineHoming.HomingLoss). L'expulsion
// n'est jamais bloquee par l'arret mecanique (comme la sortie DISABLE, contrat D2).
IF (SelMode = E_Mode.SEMI_AUTO) AND NOT MachineHomed THEN
    Auth.Mode := E_Mode.MAINT_N1;
    Auth.ModeChangePendingBlocked := TRUE;
    // Motif distinct : perte de datum EN cours de SEMI_AUTO (arret controle assure en
    // aval par MachineHoming.HomingLoss si les treuils bougeaient) vs simple selection
    // refusee. Aucune coupure de puissance, aucun redemarrage automatique.
    IF PrevArbitratedMode = E_Mode.SEMI_AUTO THEN
        Auth.ModeChangeBlockReason := 'Datum machine perdu : arret controle';
    ELSE
        Auth.ModeChangeBlockReason := 'SEMI_AUTO refuse : datum machine absent';
    END_IF;
ELSIF (SelMode <> PrevArbitratedMode)
      AND (SelMode <> E_Mode.DISABLE) AND (PrevArbitratedMode <> E_Mode.DISABLE)
      AND NOT ModeChangeAllowed THEN
    // Bascule N1/N2/SEMI_AUTO refusée : le mode courant est MAINTENU.
    // ⚠️ Exception de sécurité (contrat D2) : une transition vers ou depuis DISABLE n'est
    // JAMAIS bloquée — sortir d'un mode maintenance ne doit jamais dépendre d'un treuil à l'arrêt.
    Auth.Mode := PrevArbitratedMode;
    Auth.ModeChangePendingBlocked := TRUE;
    // Motif du blocage (texte IHM court) — première condition échouée, ordre M1 puis M2.
    IF NOT M1ContactorsReleased THEN
        ModeChangeBlockReason := 'Chgt mode refuse : contacteur M1';
    ELSIF M1BrakeIsOpen THEN
        ModeChangeBlockReason := 'Chgt mode refuse : frein M1';
    ELSIF ABS(M1SpeedAbsMps) >= MovementSpeedThresholdMps THEN
        ModeChangeBlockReason := 'Chgt mode refuse : M1 en mvt';
    ELSIF NOT M2ContactorsReleased THEN
        ModeChangeBlockReason := 'Chgt mode refuse : contacteur M2';
    ELSIF M2BrakeIsOpen THEN
        ModeChangeBlockReason := 'Chgt mode refuse : frein M2';
    ELSIF ABS(M2SpeedAbsMps) >= MovementSpeedThresholdMps THEN
        ModeChangeBlockReason := 'Chgt mode refuse : M2 en mvt';
    ELSE
        ModeChangeBlockReason := '';
    END_IF;
    Auth.ModeChangeBlockReason := ModeChangeBlockReason;
ELSE
    Auth.Mode := SelMode;
    Auth.ModeChangePendingBlocked := FALSE;
    Auth.ModeChangeBlockReason := '';
END_IF;

PrevArbitratedMode := Auth.Mode;
{endregion}

{region "§3bis Publication du re-homing obligatoire"}
// 🧭 3bis. PUBLICATION DU RE-HOMING OBLIGATOIRE
// Armement et levée réalisés en §1ter, AVANT l'arbitrage de mode — voir le commentaire §1ter
// (pas de fenêtre d'un scan, pas de perte sur coupure en cours de maintenance).
Auth.HomingRequiredM1 := MaintHomingRequiredM1;
Auth.HomingRequiredM2 := MaintHomingRequiredM2;
{endregion}

{region "§4 Calcul autorisations machine"}
// 4. SYNC ENABLE — actionnable en MAINT_N1 ou MAINT_N2
// FALSE (désactivé) seulement si en MAINT_N1/N2 ET case décochée ; TRUE partout ailleurs.
Auth.SyncEnable := NOT ((Auth.Mode = E_Mode.MAINT_N1 OR Auth.Mode = E_Mode.MAINT_N2) AND NOT SelSyncEnable);

// 4bis. TOGGLE INHIBITIONS + EXCLUSION MUTUELLE + RESET SYNC ENABLE
// Chaque bouton est un TOGGLE (écran tactile simple, pas d'appui simultané possible) :
//   - front montant d'un bouton dont le treuil n'est PAS inhibé  -> pose l'inhibition
//     et lève l'autre (exclusion mutuelle), coupe la synchro.
//   - front montant d'un bouton dont le treuil EST déjà inhibé   -> lève l'inhibition
//     (retour à l'état normal), sans toucher à l'autre ni à la synchro.
IF InhibitM1Request AND NOT PrevInhibitM1 THEN
    IF Auth.InhibitM1 THEN
        // M1 déjà inhibé -> lever (toggle off)
        Auth.InhibitM1 := FALSE;
    ELSE
        // inhiber M1, lever M2 (exclusion mutuelle)
        Auth.InhibitM1 := TRUE;
        Auth.InhibitM2 := FALSE;
        SelSyncEnable := FALSE;
    END_IF;
ELSIF InhibitM2Request AND NOT PrevInhibitM2 THEN
    IF Auth.InhibitM2 THEN
        // M2 déjà inhibé -> lever (toggle off)
        Auth.InhibitM2 := FALSE;
    ELSE
        // inhiber M2, lever M1 (exclusion mutuelle)
        Auth.InhibitM2 := TRUE;
        Auth.InhibitM1 := FALSE;
        SelSyncEnable := FALSE;
    END_IF;
END_IF;

PrevInhibitM1 := InhibitM1Request;
PrevInhibitM2 := InhibitM2Request;

Auth.InhibitM1 := (Auth.Mode = E_Mode.MAINT_N2) AND Auth.InhibitM1;
Auth.InhibitM2 := (Auth.Mode = E_Mode.MAINT_N2) AND Auth.InhibitM2;

// 4ter. AUTORISATION ARRÊT HAUT (HomingApproach)
Auth.HomingApproachEnable := (Auth.Mode = E_Mode.MAINT_N2) AND SelHomingApproachEnable;

// 4quater. SÉLECTEUR JOYSTICK TREUIL
// T248 — Gestion bucket auto : en sél. opérateur COUPLÉ (0) + toggle actif, le sens
// joystick impose d'abord l'état benne requis en forçant le sél. à 2 (jog benne),
// puis retour à 0 pour le mouvement couplé. Un seul mécanisme = le sélecteur réel.
//   manche tiré (montée)  + benne pas fermée -> 2 (ferme), puis 0 (remonte couplé)
//   manche poussé (descente) + benne pas ouverte -> 2 (ouvre), puis 0 (descend couplé)
// BucketSeqSatisfied verrouille le retour à 0 jusqu'au relâchement joystick -> pas de
// va-et-vient du sélecteur au bord de la bande de détection.
// VERROU DE PHASE : n'est effacé que par un manche au neutre CONFIRMÉ (>200 ms) -> un
// passage bref par le neutre (ajustement de prise, dip sous deadzone) NE relance PAS la
// correction benne. Hors maintenance : effacement immédiat.
TonJoyNeutralT248(IN := NOT (JoystickPull OR JoystickPush), PT := CST_T248JoyNeutralConfirm);
IF TonJoyNeutralT248.Q THEN
    BucketSeqSatisfied := FALSE;
END_IF;

Auth.CoupledBucketPhaseLocked := FALSE;

IF (Auth.Mode = E_Mode.MAINT_N2) OR (Auth.Mode = E_Mode.MAINT_N1) THEN
    // GARDE Tremie (MAINT uniquement -- ne doit PAS interferer avec SEMI_AUTO/cycle auto,
    // qui pilote la benne via ReqProgram.ReqBucket, pas ce selecteur) : a la Tremie, seul
    // le pilotage benne (WinchSel=2) est permis - le couple (0) ne doit JAMAIS s'y engager
    // manuellement, meme via T248 (BucketSeqSatisfied pouvait se lever a tort si la benne
    // etait deja ouverte d'une action precedente -> bascule 0 -> tentative descente couplee
    // -> M1 a bouge a la Tremie, REX MES 2026-09-04). Echappatoire consciente : bit IHM
    // AllowWinchMoveAtTremie (T249) leve la garde -> retour au comportement T248 normal.
    IF M3AtTremie AND NOT AllowWinchMoveAtTremie THEN
        Auth.JoystickWinchSelectArbitrated := 2;
        BucketSeqSatisfied := FALSE;
    ELSIF CoupledBucketSeqEnable
       AND (JoystickWinchSelectRequest = 0)
       AND (JoystickPull XOR JoystickPush) THEN
        // TOUTE la séquence T248 (jog ET couplé) "possède" la benne : elle est pilotée
        // par le jog WinchSel=2, jamais par instBucket. -> on inhibe pour toute la durée
        // l'armement dive-open/ascent-close de FB_BucketCmdArbitration : plus de blip
        // instBucket.Lifecycle.Busy sur la bascule 2->0 -> plus de perte du deadman via
        // ArmBucketBusy (PRG_04), plus de blocage/correction sur l'état benne temps réel.
        Auth.CoupledBucketPhaseLocked := TRUE;
        // SET du verrou de phase dès que la benne est dans l'état requis par le sens.
        IF (JoystickPull AND BucketIsClosed) OR (JoystickPush AND BucketIsOpen) THEN
            BucketSeqSatisfied := TRUE;
        END_IF;
        IF BucketSeqSatisfied THEN
            Auth.JoystickWinchSelectArbitrated := 0;   // phase COUPLÉE : on ne recorrige
                                                       // plus la benne, perte d'état ignorée.
        ELSE
            Auth.JoystickWinchSelectArbitrated := 2;   // phase JOG : amener la benne dans l'état
        END_IF;
    ELSE
        Auth.JoystickWinchSelectArbitrated := JoystickWinchSelectRequest;
    END_IF;
ELSE
    Auth.JoystickWinchSelectArbitrated := 0;  // Couplé nominal forcé
    BucketSeqSatisfied := FALSE;
END_IF;

// HOLD DE TRANSITION : à chaque changement du sélecteur arbitré (jog<->couplé), on force
// l'arrêt des requêtes M1/M2 (PRG_04) pendant une PAUSE FIXE de 300 ms -> pas de hand-off
// en mouvement, redémarrage rampé. Dwell fixe (pas de condition vitesse) : auto-libéré,
// impossible à bloquer, aucun retour au neutre requis. Le verrou de phase empêche le
// sélecteur d'osciller, donc au plus une pause par changement franc.
WinchSelChangedT248 := (Auth.JoystickWinchSelectArbitrated <> WinchSelPrevT248);
WinchSelPrevT248 := Auth.JoystickWinchSelectArbitrated;
TonWinchSelSettle(IN := NOT WinchSelChangedT248, PT := CST_T248TransitionSettle);
Auth.WinchSelTransitionHold := NOT TonWinchSelSettle.Q;

// 4quinquies. CIBLE TRANSLATION MAINTENANCE
Auth.MaintenanceM3TargetEnable := ((Auth.Mode = E_Mode.MAINT_N2) OR (Auth.Mode = E_Mode.MAINT_N1)) AND SelMaintenanceZoneAccess;

// Re-vérification sécurité si sortie MAINT
IF (Auth.Mode <> E_Mode.MAINT_N2) AND (Auth.Mode <> E_Mode.MAINT_N1) THEN
    Auth.InhibitM1 := FALSE;
    Auth.InhibitM2 := FALSE;
    Auth.HomingApproachEnable := FALSE;
    Auth.MaintenanceM3TargetEnable := FALSE;
    Auth.JoystickWinchSelectArbitrated := 0;
    BucketSeqSatisfied := FALSE;
    Auth.CoupledBucketPhaseLocked := FALSE;
    Auth.WinchSelTransitionHold := FALSE;
END_IF;
{endregion}

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}
